def themed(page):
    """Dark or light pages, per Settings (doesn't depend on the phone's own setting)."""
    if "</head>" in page and "color-scheme:" not in page.split("</head>")[0][-1200:]:
        page = page.replace("</head>", (DARK_CSS if CFG.get("dark") else LIGHT_CSS) + "</head>", 1)
    return page


def with_nav(page):
    """Every page gets the app frame and the chosen colours."""
    return app_frame(themed(page))


def replace_page(web, page):
    """Put a whole new page into the one already showing (no blank white reload).
    False if the current page can't do that, so the caller loads it normally."""
    try:
        if web.evaluate_javascript("typeof window.__load") == "function":
            web.evaluate_javascript("window.__load(%s)" % json.dumps(page))
            return True
    except Exception:
        pass
    return False


def swap_page(webview, page):
    """Redraw the page you're on without jumping to the top (falls back to a full reload)."""
    page = with_nav(page)
    body = page.split("<body>", 1)[1].rsplit("</body>", 1)[0] if "<body>" in page else None
    try:
        if body is None:
            raise ValueError
        webview.evaluate_javascript("window.__swap(%s)" % json.dumps(body))
    except Exception:
        webview.load_html(page)


def present(page, keeper=None):
    """Show a page in the same window (no sliding away). Browser outside Pythonista."""
    page = with_nav(page)
    if not in_pythonista():
        import webbrowser
        path = os.path.join(HERE, "combos_view.html")
        with open(path, "w", encoding="utf-8") as f:
            f.write(page)
        print(f"Page saved to {path}")
        webbrowser.open("file://" + path)
        return
    web = _web()
    web.delegate = NavKeeper(keeper)
    screen = (APP.get("where"), (re.search(r"<title>([^<]*)</title>", page) or re.search(r"<h1>([^<]*)", page) or [None, ""])[1])
    body = page.split("<body>", 1)[1].rsplit("</body>", 1)[0] if "<body>" in page else None
    if APP.get("page") == "page" and APP.get("screen") == screen and body is not None:
        try:
            web.evaluate_javascript("window.__swap(%s)" % json.dumps(body))
            APP["quiet"] = False
            return
        except Exception:
            pass
    if not (APP.get("page") in ("page", "loading") and replace_page(web, page)):
        web.load_html(page)
    APP["page"] = "page"
    APP["screen"] = screen
    APP["quiet"] = False


MINE = {"live": False, "thread": None, "hold": {}, "cash": {}}


def show_mine(all_games, days, sunday):
    """Your combos already placed on Kalshi for this week, with optional live alerts."""
    APP["where"] = "mine"
    book, notes = {}, []
    loading("Getting sportsbook odds…")
    book, n = fetch_book_odds(CFG["odds_key"])
    notes.append(n)
    MINE.update({"all_games": all_games, "days": days, "sunday": sunday, "book": book,
                 "notes": notes, "live": False, "last": None})
    page, MINE["snap"] = mine_page()

    present(page, MineKeeper())
    if CFG.get("auto_live", True) and MINE.get("hold") and APP.get("web") is not None and in_pythonista():
        set_live(APP["web"], True)


@safe_delegate
class MineKeeper:
    def webview_should_start_load(self, webview, url, nav_type):
        if url.startswith("combo://live/"):
            set_live(webview, url.endswith("/on"))
            return False
        if url.startswith("combo://cash/"):
            import threading
            action, _, ticker = url[len("combo://cash/"):].partition("/")
            threading.Thread(target=cash_action, args=(action, ticker.strip("/")), daemon=True).start()
            return False
        if url.startswith("combo://settings"):
            MINE["live"] = False
            reopen_settings(webview)
            return False
        return not url.startswith("combo://")


def set_live(webview, on):
    """Turn game-day alerts on/off. While on: check every 2 minutes, refresh, notify."""
    import threading
    MINE["live"] = on
    try:
        import console
        console.set_idle_timer_disabled(on)      # keep the screen awake while watching
    except Exception:
        pass
    if on and not (MINE["thread"] and MINE["thread"].is_alive()):
        MINE["thread"] = threading.Thread(target=live_loop, args=(webview,), daemon=True)
        MINE["thread"].start()
    elif not on:
        webview.evaluate_javascript("liveState(false, '')")


def live_loop(webview):
    import time
    first = True
    while MINE["live"] and window_open():
        if not first:
            for _ in range(max(5, int(CFG.get("refresh_secs", 15)))):   # stop quickly when switched off
                if not MINE["live"] or not window_open():
                    return
                time.sleep(1)
        first = False
        try:
            live_check(webview)
        except Exception as err:
            try:
                webview.evaluate_javascript("liveState(true, %s)" % json.dumps(
                    f"Couldn't check just now ({str(err)[:60]}). Trying again in 2 minutes."))
            except Exception:
                pass


def live_check(webview):
    """One refresh: current prices and results, redraw the page, send any alerts."""
    all_games, days, _ = week_games(fetch_markets(), loose=True)
    MINE["all_games"].update(all_games)    # current prices, keeps finished games
    try:
        attach_fair(all_games, {})             # Kalshi's prices, for the kickoff record
        record_closing(all_games)
    except Exception:
        pass
    MINE["days"].update(days)
    MINE["book"] = {}                      # live chances use Kalshi's in-game prices
    if MINE.get("busy"):
        return []
    MINE["last"] = dt.datetime.now().strftime("%-I:%M %p")
    expire_offers()
    pre_alerts = auto_cash_checks()
    APP["quiet"] = True
    page, snap = mine_page(live=True)
    pi = in_pythonista() and watcher_alive()
    if AUTOSELL and CFG.get("tp_follow", True) and MINE.get("tp") and can_trade() and not pi:
        try:
            if retarget_take_profits():
                MINE["tp"] = resting_sells()
                page, snap = mine_page(live=True)
        except Exception:
            pass
    if pi:
        MINE["pi_was_alive"] = True
    elif MINE.get("pi_was_alive") and watcher_conf():
        MINE["pi_was_alive"] = False             # the Pi went quiet: say so once, the phone takes over
        notify(f"🖥 Your {wname()} watcher stopped checking in. This phone is handling alerts and auto cash-out "
               f"while the planner is open. Check the {wname()}'s power and network.")
    sold = [] if pi else auto_sell_now(MINE.get("plan"))     # with the Pi on, only the Pi sells
    if sold:
        ACCT_CACHE["at"] = 0
        MINE["flash"] = " ".join(sold)
        page, snap = mine_page(live=True)
        for msg in sold:
            notify(msg)
    cash_alerts_now = [] if sold else cash_alerts(MINE.get("plan"))
    alerts = diff_alerts(MINE.get("snap") or {}, snap) + pre_alerts + cash_alerts_now
    MINE["snap"] = snap
    present(page, MineKeeper())
    for msg in ([] if pi else alerts[:4]):        # the Pi sends these when it's running
        notify(msg)
    return alerts


SELL_LOG = os.path.join(HERE, "combo_autosell_log.jsonl")   # every automatic cash-out decision, one per line


SELL_TOLD = {}             # ticker -> (result, why, offer band) of the last skip logged (no 12-second repeats, #115)
SELL_KEEP = 3000          # other decision lines kept in the file; sales, hedges and "check"s are never trimmed
SALE_RESULTS = ("sold", "hedged", "check", "failed", "hedge check", "hedge failed")


def device_label():
    """Which device made a decision: the phone (Pythonista), the Pi (alerts-only backup) or the Mac."""
    return "phone" if in_pythonista() else "pi" if role_backup() else "mac"


def _skip_repeat(rec):
    """True when this skip says what the last one for the same bet said (same reason, offer within the same 10% of
    cost): it isn't written again. A new reason or a different offer band is written once more."""
    if rec.get("result") != "skipped":
        if rec.get("ticker"):
            SELL_TOLD.pop(rec["ticker"], None)
        return False
    cost = rec.get("cost") or 0
    band = int((rec.get("offer") or 0) / cost * 10) if cost else None
    sig = (rec.get("why"), band)
    t = rec.get("ticker") or rec.get("combo") or ""
    if SELL_TOLD.get(t) == sig:
        return True
    if len(SELL_TOLD) > 2000:
        SELL_TOLD.clear()
    SELL_TOLD[t] = sig
    return False


def _fail_stamp_due(rec):
    """False only for a repeat of a plain failed cash-out ("failed"/"hedge failed": nothing was sold) on the same bet
    within MONEY_FAIL_GAP seconds (#271): a loop logging the same failure every pass must not make every open screen
    force a fresh Kalshi account read each time. Sold, hedged and every unclear ("check") result always stamp."""
    if rec.get("result") not in ("failed", "hedge failed"):
        return True
    t, now = (str(rec.get("ticker") or rec.get("combo") or ""), rec.get("result")), time.time()
    if now - MONEY_FAIL_AT.get(t, 0) < MONEY_FAIL_GAP:
        return False
    if len(MONEY_FAIL_AT) > 2000:
        MONEY_FAIL_AT.clear()
    MONEY_FAIL_AT[t] = now
    return True


def _trim_sell_log():
    """Keeps every sale, hedge and unclear order, and the newest SELL_KEEP other lines."""
    with open(SELL_LOG, encoding="utf-8") as f:
        lines = f.readlines()
    keep, other = [], 0
    for line in reversed(lines):
        sale = any(f'"result": "{r}"' in line for r in SALE_RESULTS)
        if sale or other < SELL_KEEP:
            keep.append(line)
            other += not sale
    tmp = SELL_LOG + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.writelines(reversed(keep))
    os.replace(tmp, SELL_LOG)


SELL_LOG_LOCK = threading.Lock()   # the trim reads and rewrites the file: no line appended in between is lost


def log_decision(rec):
    """One line per automatic cash-out decision (sold, or skipped and why). A skip is written once per bet and
    reason (again when the reason or the offer's band changes), so the file covers weeks, not hours; sales are never
    trimmed, and each sale is also kept in the history file for the smart-sell scorecard (#115)."""
    import time
    if _skip_repeat(rec):
        return
    rec = dict(rec, at=int(time.time()), when=dt.datetime.now().strftime("%Y-%m-%d %H:%M"),
               by=device_label(), ride=ride_level()[0])
    try:
        with SELL_LOG_LOCK:
            with open(SELL_LOG, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec) + "\n")
            if os.path.getsize(SELL_LOG) > 1500000:
                _trim_sell_log()
    except OSError:
        pass
    if rec.get("result") in SALE_RESULTS and _fail_stamp_due(rec):
        money_mark()                             # display only (#242): open screens refresh now
    try:
        if rec.get("result") in SALE_RESULTS:
            sale_store(rec)
    except Exception as err:
        print("sale log:", type(err).__name__, err)
    console_note("auto cash-out: " + json.dumps(rec))


AUTO_CAP_MAX = 10           # the Auto cash-outs a day slider's highest number; its next stop is "Unlimited"
AUTO_CAP_UNLIMITED = 1000   # stored for "Unlimited" (issue #217): an older process reads it as a cap of 1000 a day


def auto_cap_limit(v=None):
    """Today's limit on automatic cash-outs: a number, or None for Unlimited (anything over AUTO_CAP_MAX).
    A value that can't be read falls back to the default 5, never to unlimited."""
    try:
        n = int(float(CFG.get("auto_cap", 5) if v is None else v))
    except (TypeError, ValueError, OverflowError):
        n = 5
    return None if n > AUTO_CAP_MAX else n


def auto_cap_reached():
    """This device already made today's allowed automatic cash-outs ("check" sales count). Never with Unlimited."""
    lim = auto_cap_limit()
    return lim is not None and sold_today() >= lim


def sold_today():
    """Automatic cash-outs made by this device today."""
    today = dt.date.today().isoformat()
    try:
        with open(SELL_LOG, encoding="utf-8") as f:
            return sum(1 for x in f if ('"result": "sold"' in x or '"result": "hedged"' in x or '"result": "check"' in x)
                       and f'"when": "{today}' in x)     # a "check" sale may have gone through: it counts
    except OSError:
        return 0


def turning_against(h):
    """A game in this combo is on and going the wrong way (your pick under 50% live)."""
    return any(live and c < 0.5 for c, live, _ in h.get("legs_left") or [])


# ---------------------------------------------------------------- the stop-loss switch, guarded (issue #27)
# Pete's rule (2026-11-23, #382): auto-sell never sells below what you paid EXCEPT to lose less than waiting would (the
# learned loss cut, or this guarded stop-loss); a sale that was a profit never takes a fresh offer below cost. Under
# (the 'Never sell at a loss' choice was removed). The stop-loss switch (off by default) lifts the "never below what you paid"
# guard for the stop-loss path only,
# once ALL of these hold for a pick in the combo: its game is really under way on a fresh score feed (no feed or a
# stale one: never), late enough in the game, not at halftime or a break, the pick has fallen a long way from its
# chance before the game (and is now under 50%), and that has held on 3+ checks in a row over at least 3 minutes.
# How late and how big a fall are learned league by league (smart_tune); they start conservative and only a
# league's own record can loosen them below the start.
SL_DEFAULT = {"prog": 0.50, "drop": 0.20}      # at least half the game played; at least 20 points under its pregame chance
SL_BOUNDS = {"prog": (0.35, 0.90), "drop": (0.10, 0.45)}
SL_STEP = 0.05
SL_MIN_N, SL_MIN_GAIN = 50, 0.02               # combos with recorded game prices before a league's own settings move
SL_CHECKS, SL_SPAN, SL_GAP = 3, 180, 300       # 3+ checks in a row, spanning 3+ minutes, none more than 5 minutes apart
SL_FEED_AGE = 150                              # a score older than this (seconds) is stale: no loss sale
SL_UNDER = 0.5                                 # a loss sale needs the pick under this chance (50%) right now

# ---------------------------------------------------------------- learned guards (Pete: "allow some level of learning")
# Three fixed selling guards become learned settings, on the same machinery as the exit knobs (the registry, the weekly
# stepper, the brake, the evidence bar, the shadow move log), behind Settings > Cash out `learned_guards` (default ON,
# effective only together with `knobs_live`; either one off = exactly develop):
#   * the score-age tolerance (`sl_feed_age`, start 150 s, 90-300 s in 30 s steps): learned from `feed_ep`, episodes where
#     only a stale score held a loss sale back (what selling then got after fees against 10 minutes later);
#   * acting at a halftime or break (`brk_on` / `brk_move`): the existing break_ep episodes, now allowed to go live for
#     a LOSS sale only (never a hedge) once a league has BRK_MIN_N of its own and the judge's bar is met;
#   * "too early in the game" (`sl_prog`) is already learned (smart_tune, then the stepper): nothing new moves it.
# A loosening step also needs a bootstrap range above zero in net dollars; a tightening one is held to a lighter bar.
# What never moves: no score at all, a game not under way, a one-sided or empty book, Pause, rule 8, the manual Sell.
GUARD_KNOBS = ("sl_feed_age", "brk_on", "brk_move")
GUARD_SWITCH = {"at": 0.0, "on": None}
FEED_BAND = (90, 300)                          # the registry's bounds for sl_feed_age: episodes outside it teach nothing
FEED_WAIT, FEED_DROP, FEED_KEEP_ROWS = 600, 1800, 5000   # what waiting did: the price 10 min later (dropped after 30)
FEED_MIN_N = 20                                # a league's own episodes before the judge may step the age
KNOB_SHADOW_ROWS = 20000                       # the move log (knob_shadow) keeps this many rows at most
BRK_KEEP_ROWS = 5000                           # the break_ep shadow table, with the learned guards on
GUARD_BOOT = {"n": 400, "pct": 0.05}           # bootstrap resamples, and the lower percentile that must be above 0
GUARD_TIGHT = {"band_n": 5, "gain": 0.02, "se": 1.5, "new": 10, "holdout": 0.30}   # a tightening step's lighter bar
FEED_EP = {}                                   # (ticker, side) -> the open episode, until its 10 minutes are up
FEED_ERR = {"at": 0.0}


def guards_on():
    """Settings > Cash out 'Let the selling guards learn' (`learned_guards`, on by default) AND `knobs_live`: both must
    be on. Cached 10 s like knob_switch_on; an unreadable settings file or any error counts as off (develop's rules)."""
    t = time.monotonic()
    if GUARD_SWITCH["on"] is None or t - GUARD_SWITCH["at"] > 10:
        try:
            on = bool(knob_switch_on() and shared_flag("learned_guards"))
        except Exception:
            on = False
        GUARD_SWITCH.update(at=t, on=on)
    return bool(GUARD_SWITCH["on"])


def guards_view(key):
    """Read-only text for Settings: what each learned selling guard stands at for league `key` right now, in plain
    words ({stale, brk, on}). Never raises; the starting values when the guards are off or nothing is recorded."""
    out = {"on": False, "stale": "%d seconds (the starting value)" % SL_FEED_AGE,
           "brk": "blocked: no sale at halftime or a break"}
    try:
        if not guards_on():
            return out
        out["on"] = True
        st, sm, now = knob_state_cached(), smart_table(), time.time()
        age, g = knob_live_value("sl_feed_age", key, None, st, sm, now)
        on_, g2 = knob_live_value("brk_on", key, None, st, sm, now)
        mv, _ = knob_live_value("brk_move", key, None, st, sm, now)
        out["stale"] = ("%d seconds (the starting value)" % age if age == SL_FEED_AGE else
                        "%d seconds, learned from this app's own sales" % age)
        out["brk"] = ("a loss sale may go through at a break only after a move of %d points or more, learned from this "
                      "app's own sales" % round(mv * 100) if on_ == 1 else
                      "blocked: no sale at halftime or a break until %d break episodes show it pays after fees"
                      % BRK_MIN_N)
    except Exception as err:
        print("guards view:", type(err).__name__, err)
    return out


def knob_live_names():
    """The knobs that act live: KNOB_LIVE, plus the three learned guards while `guards_on()`."""
    return KNOB_LIVE + GUARD_KNOBS if guards_on() else KNOB_LIVE


def feed_age_limit(ticker, loose=False):
    """How old a live score may be (seconds) before this pick's game counts as stale: SL_FEED_AGE (150) unless the
    learned guards are on and this league has its own value (a borrowed one is only stricter, as every knob). Only the
    loss sale (`loose=True`) may use a value above 150; the hedge and the 'sell more' check never go looser than today.
    Any error, a missing, non-numeric or out-of-range value gives 150."""
    if not guards_on():
        return SL_FEED_AGE
    try:
        k, chain = _knob_bet_chain([ticker])
        v, _ = knob_live_value("sl_feed_age", k, chain, knob_state_cached(), {}, time.time())
        if v is None or not _knob_valid("sl_feed_age", v):
            return SL_FEED_AGE
        return v if loose else min(v, SL_FEED_AGE)
    except Exception:
        return SL_FEED_AGE


def _feed_table():
    if STORE.get("db") and not STORE.get("feed_ok"):
        store_x("create table if not exists feed_ep(ts real, ticker text, side text, league text, age real, bid real, "
                "later real)")
        store_x("create index if not exists feed_ep_t on feed_ep(ts)")
        STORE["feed_ok"] = bool(store_rows("select name from sqlite_master where type='table' and name='feed_ep'"))


def feed_resolve(now=None):
    """Closes the open score-age episodes whose 10 minutes are up: what the pick's bid was then (from a price the engine
    already read, never fetched) is written to `feed_ep`. One that can't be priced within 30 minutes is dropped. The
    table keeps its newest FEED_KEEP_ROWS. Never raises."""
    try:
        now = now or time.time()
        for key, ep in list(FEED_EP.items()):
            if now - ep["ts"] < FEED_WAIT:
                continue
            bk = _brk_book(key[0], key[1], now) if now - ep["ts"] <= FEED_DROP else None
            if bk and STORE.get("db"):
                _feed_table()
                store_x("insert into feed_ep(ts, ticker, side, league, age, bid, later) values(?,?,?,?,?,?,?)",
                        (ep["ts"], key[0], key[1], ep["league"], ep["age"], ep["bid"], bk[0]))
                store_x("delete from feed_ep where rowid not in (select rowid from feed_ep order by ts desc limit ?)",
                        (FEED_KEEP_ROWS,))
            if bk or now - ep["ts"] > FEED_DROP:
                FEED_EP.pop(key, None)
    except Exception as err:
        if time.time() - FEED_ERR["at"] > 600:
            FEED_ERR["at"] = time.time()
            print("score-age episodes:", type(err).__name__, err)


def feed_note(ticker, side, pre, now_ch, pr, now=None, watch=None):
    """Records one score-age episode for the judge (only while the learned guards are on; reads only, never raises):
    a time every OTHER loss guard held (in play, not at a break, far enough into the game, the drop) while the score was
    90-300 s old, with the pick's bid then (one per pick per 10 minutes). Its bid 10 minutes later is added by
    feed_resolve. Selling then against waiting is what the judge compares."""
    try:
        if not guards_on() or pre is None or now_ch is None:
            return
        now = now or time.time()
        feed_resolve(now)
        sc = leg_score({"ticker": ticker, "side": side})
        if not sc or sc.get("state") != "in" or at_break(sc):
            return
        played = game_played(sc)
        if played is None or played < pr["prog"] or now_ch >= SL_UNDER or pre - now_ch < pr["drop"]:
            return
        age = score_age(ticker_sport(ticker) or "", now)
        if not (FEED_BAND[0] <= age <= FEED_BAND[1]):
            return
        wt, ws = watch or (ticker, side)
        key = (wt, ws or "yes")
        if key in FEED_EP:
            return
        bk = _brk_book(wt, key[1], now)
        if not bk or not math.isfinite(bk[0]):
            return
        while len(FEED_EP) > 200:
            FEED_EP.pop(next(iter(FEED_EP)), None)
        FEED_EP[key] = {"ts": now, "age": round(age, 1), "bid": bk[0], "league": _knob_bet_chain([wt])[0]}
    except Exception as err:
        if time.time() - FEED_ERR["at"] > 600:
            FEED_ERR["at"] = time.time()
            print("score-age episodes:", type(err).__name__, err)


def stoploss_params(tickers):
    """How late in the game, and how big a fall from the pregame chance, the stop-loss switch needs for this bet:
    its league's own learned settings once it has enough results, else its sport's, else everyone's, else the
    conservative start. Borrowed settings can only make it stricter, never looser than the start.
    #228 PR5: with 'Let smart sell tune its own numbers' on, both come from self-tuning's live record
    (knob_live_value: the same walk, its own steps included, the start while the league's brake holds); off, or on
    any error, exactly as before."""
    if knob_switch_on():
        try:
            k, chain = _knob_bet_chain(tickers)
            st, smart, now = knob_state_cached(), smart_table(), time.time()
            pv, pg = knob_live_value("sl_prog", k, chain, st, smart, now)
            dv, _ = knob_live_value("sl_drop", k, chain, st, smart, now)
            if _knob_valid("sl_prog", pv) and _knob_valid("sl_drop", dv):
                return {"prog": float(pv), "drop": float(dv), "key": None if pg == "brake" else pg}
        except Exception as err:
            _knob_err("the loss guards' numbers", err)
    d = smart_table()
    k = bet_key(tickers)
    sport = ticker_sport(next(iter(tickers), "") or "") if k != "mix" else None
    for key in (k, sport, "all"):
        e = d.get(key) if key else None
        if e and e.get("sl_n", 0) >= SL_MIN_N and e.get("sl_prog") is not None:
            out = {"prog": float(e["sl_prog"]), "drop": float(e.get("sl_drop", SL_DEFAULT["drop"])), "key": key}
            if key != k:
                out.update(prog=max(out["prog"], SL_DEFAULT["prog"]), drop=max(out["drop"], SL_DEFAULT["drop"]))
            return out
    return dict(SL_DEFAULT, key=None)


def score_age(code, now=None):
    """Seconds since this league's scores were last fetched successfully (a failed fetch keeps the old copy)."""
    now = now or time.time()
    at = (SCORES_BY.get(code) or {}).get("at", 0)
    if code == LEAGUE["code"]:
        at = max(at, SCORES.get("at", 0))
    return now - at if at else 1e9


def at_break(sc):
    """Halftime, an intermission or the end of a period (the book thins and prices wander)."""
    det = str(sc.get("detail") or "")
    return bool(sc.get("brk")) or det == "Half" or det.startswith("End") or \
        bool(re.search(r"\b0:00$", det)) or bool(re.search(r"\b(Q|P|H)\d+ 0\.0$", det))


# ---------------------------------------------------------------- acting at a break (#228 PR5: break_ok, WATCH-ONLY)
# A loss sale or a hedge waits out halftime, an intermission or the end of a period, because the book thins and prices
# wander. Pete (2026-11-21): that shouldn't be a hard limit, since real news can land at a break (a star ruled out at
# halftime). The rule that would replace it, `break_ok`: act at a break only when a fresh two-sided order book (gap
# within LIVE_SPREAD) shows the pick's price has moved at least `brk_move` (start 8 points) since the break began, held
# on BRK_READS reads at least BRK_SPACE seconds apart (fresh injury news halves the move), and a real fresh Kalshi price
# is still read before anything is sold. It starts OFF in every league and NEVER acts live in this build (BRK_LIVE is
# False and `brk_on` is not a live knob): today it only records break episodes (`break_ep` table, from prices the engine
# already read: no new Kalshi or ESPN request) and what it would have done, so the weekly judge can replay it (40+
# episodes of a league's own, a gain of 2%+, 2+ standard errors, the newest 30% agreeing) before a later build may let
# it act.
BRK_MOVE = 0.08                 # the move a break must show (share of the payout: 8 points)
BRK_READS, BRK_SPACE = 2, 60    # held on 2 reads at least 60 s apart
BRK_FRESH = 60                  # a book read older than this isn't fresh
BRK_MIN_N = 40                  # a league's own break episodes before the judge may step it
BRK_LIVE = False                # the hard gate: nothing acts at a break in this build, whatever is recorded
BRK_EP = {}                     # (ticker, side) -> the open break episode


def _brk_book(ticker, side, now):
    """(bid, ask, mid) on the pick's side from the last price the engine read for this market, only when it is fresh
    and two-sided with a gap within LIVE_SPREAD; else None. Never fetches."""
    seen = PRICE_SEEN.get(ticker)
    if not seen or now - seen[0] > BRK_FRESH:
        return None
    bid, ask = seen[1], seen[2]
    if not bid or not ask or ask < bid or ask - bid > LIVE_SPREAD + 1e-9:
        return None
    if side == "no":
        bid, ask = round(1 - ask, 4), round(1 - bid, 4)
    return bid, ask, round((bid + ask) / 2, 4)


def _brk_news(ticker, sc):
    """Fresh injury news (the last 3 hours) for either team, from a report already cached (never fetched here)."""
    try:
        code = ticker_sport(ticker) or ""
        got = INJ.get(code)
        if not got or time.time() - got[0] > 1500:      # a margin under league_injuries' 1800 s: never fetches here
            return False
        teams = [x for x in (sc.get("name"), sc.get("team"), sc.get("opp_name")) if isinstance(x, str) and x]
        return bool(teams) and bool(injury_note(code, *teams, hours=3)[1])
    except Exception:
        return False


def brk_fires(reads, mid0, move, news=False):
    """The index of the read at which break_ok's rule holds: the pick's mid at least `move` (half with news) from where
    the break began, on BRK_READS reads in a row spanning BRK_SPACE seconds. None = it never does. reads = [(ts, bid,
    mid)]."""
    if move is None or mid0 is None:
        return None
    need = move / 2 if news else move
    run = []
    for i, (ts, _, mid) in enumerate(reads or ()):
        if mid is not None and abs(mid - mid0) >= need - 1e-9:
            run.append(ts)
            if len(run) >= BRK_READS and run[-1] - run[0] >= BRK_SPACE:
                return i
        else:
            run = []
    return None


def _brk_table():
    if STORE.get("db") and not STORE.get("brk_ok"):
        store_x("create table if not exists break_ep(ts real, ticker text, side text, league text, detail text, "
                "news int, reads text, after_bid real, after_ts real, would real)")
        store_x("create index if not exists break_ep_t on break_ep(ts)")
        STORE["brk_ok"] = bool(store_rows("select name from sqlite_master where type='table' and name='break_ep'"))


def break_watch(ticker, side, sc, now=None):
    """Records break episodes for the judge (watch-only, never raises, never fetches): while this pick's game is at a
    break, the pick's price every 20 s or more from prices the engine already read; once play resumes, the price just
    after the break, and the episode is written to `break_ep` (with when break_ok would have acted, at the league's
    test value of brk_move). A game that ends at the break, or an episode over 2 hours old, is dropped."""
    try:
        now = now or time.time()
        key = (ticker, side or "yes")
        ep = BRK_EP.get(key)
        if ep and now - ep["start"] > 7200:
            BRK_EP.pop(key, None)
            ep = None
        if not sc or sc.get("state") != "in":
            BRK_EP.pop(key, None)
            return
        if at_break(sc):
            if ep is None:
                while len(BRK_EP) > 400:             # (#316) drop the oldest episode, not every open one
                    BRK_EP.pop(next(iter(BRK_EP)), None)
                ep = BRK_EP[key] = {"start": now, "detail": str(sc.get("detail") or "")[:40], "reads": [],
                                    "news": _brk_news(ticker, sc), "would": None}
                price_watch([ticker], hours=3)        # its price path (with score lines) is recorded too
            bk = _brk_book(ticker, key[1], now)
            if bk and (not ep["reads"] or now - ep["reads"][-1][0] >= 20) and len(ep["reads"]) < 60:
                ep["reads"].append((round(now), bk[0], bk[2]))
                if ep["would"] is None:
                    mv = knob("brk_move", _knob_bet_chain([ticker])[0], st=knob_state_cached())
                    i = brk_fires(ep["reads"], ep["reads"][0][2], mv, ep["news"])
                    if i is not None:
                        ep["would"] = ep["reads"][i][0]
            return
        if ep is None:
            return
        BRK_EP.pop(key, None)
        bk = _brk_book(ticker, key[1], now)
        if not bk or not ep["reads"] or not STORE.get("db"):
            return
        _brk_table()
        store_x("insert into break_ep(ts, ticker, side, league, detail, news, reads, after_bid, after_ts, would) "
                "values(?,?,?,?,?,?,?,?,?,?)",
                (ep["start"], ticker, key[1], _knob_bet_chain([ticker])[0], ep["detail"], int(bool(ep["news"])),
                 json.dumps(ep["reads"]), bk[0], round(now), ep["would"]))
    except Exception as err:
        if time.time() - BRK_ERR["at"] > 600:
            BRK_ERR["at"] = time.time()
            print("break episodes:", type(err).__name__, err)


BRK_ERR = {"at": 0.0, "hedge": 0.0}


def break_ok(ticker, side, sc, now=None, what="loss", watch=None):
    """At a break: may a loss sale or hedge act anyway? Records the episode (break_watch). The old rule (wait out the
    break) stands unless the learned guards are on (`guards_on()`) and the sale is a LOSS sale (never a hedge): then a
    league's own record must have switched `brk_on` on (BRK_MIN_N episodes that pay after fees, a bootstrap range above
    zero), the rule must hold on its reads (brk_fires at its brk_move) and a fresh two-sided order book read now
    (max_age=0) must still show the move. BRK_LIVE (the old, unlearned way of opening it) stays off."""
    wt, ws = watch or (ticker, side)                  # (#316) a single's episode is filed under the held market
    break_watch(wt, ws, sc, now)
    if BRK_LIVE:
        if "brk_on" not in KNOB_LIVE or not knob_switch_on():
            return False
    elif what != "loss" or not guards_on() or "brk_on" not in knob_live_names():
        return False                                  # develop's rule; the learned guards open a LOSS sale only
    try:
        k = _knob_bet_chain([ticker])[0]
        if knob("brk_on", k) != 1:
            return False
        ep = BRK_EP.get((wt, ws or "yes"))
        if not ep or not ep["reads"]:
            return False
        mv = knob("brk_move", k)
        if brk_fires(ep["reads"], ep["reads"][0][2], mv, ep["news"]) is None:
            return False
        bk = book_depth(ticker, max_age=0)
        if not bk or not bk.get("bid") or not bk.get("ask") or bk.get("spread") is None or bk["spread"] > LIVE_SPREAD:
            return False
        mid = (bk["bid"] + bk["ask"]) / 2
        mid = 1 - mid if (side or "yes") == "no" else mid
        return ep["reads"][0][2] - mid >= (mv / 2 if ep["news"] else mv) - 1e-9   # a loss sale needs the price DOWN (review P2)
    except Exception:
        return False


def game_played(sc):
    """Share of the game played (0..1) from the score feed's period and clock, or None when it can't say."""
    if not sc or sc.get("state") != "in" or sc.get("frac") is None:
        return None
    return round(1 - float(sc["frac"]), 3)


def fresh_live_score(ticker, side, now=None, loose=False):
    """This pick's game on a fresh score feed, while it's in play: (score, '') or (None, why not). Shared by every
    guard that acts on a live game (the stop-loss switch, the learned loss cut, auto-hedge). The age limit is
    SL_FEED_AGE (150 s); with the learned guards on, a league's own learned limit (`feed_age_limit`), which only the
    loss sale (`loose=True`) may use above 150. No score at all is always 'no score feed'."""
    sc = leg_score({"ticker": ticker, "side": side})   # never Kalshi's live data (display only)
    if not sc:
        return None, "no score feed"
    age = score_age(ticker_sport(ticker) or "", now)
    if age > feed_age_limit(ticker, loose):
        return None, "score feed stale"
    if sc.get("state") != "in":
        return None, "game not under way"
    if age > SL_FEED_AGE:                             # a learned wider age: a break may hide inside it, so ask the book
        bk = book_depth(ticker, max_age=0)            # (fresh and two-sided, as break_ok does), else stale (review P3)
        if not bk or not bk.get("bid") or not bk.get("ask") or bk.get("spread") is None or bk["spread"] > LIVE_SPREAD:
            return None, "score feed stale"
    return sc, ""


def stop_loss_leg(ticker, side, pre, now_ch, pr, now=None, watch=None):
    """Whether one pick passes every stop-loss guard right now: (True, '') or (False, why not)."""
    sc, why = fresh_live_score(ticker, side, now, loose=True)
    if not sc:
        if why == "score feed stale":
            feed_note(ticker, side, pre, now_ch, pr, now, watch)
        return False, why
    if pre is None or now_ch is None:
        return False, "no pregame chance"
    if at_break(sc) and not break_ok(ticker, side, sc, now, "loss", watch):
        return False, "halftime or a break"
    played = game_played(sc)
    if played is None or played < pr["prog"]:
        return False, "too early in the game"
    if now_ch >= SL_UNDER or pre - now_ch < pr["drop"]:
        return False, "not far enough below its pregame chance"
    feed_note(ticker, side, pre, now_ch, pr, now, watch)
    return True, ""


def _sl_confirm(key, hit, why, now, cf=None):
    """The 'held on SL_CHECKS checks in a row spanning SL_SPAN seconds, none more than SL_GAP apart' part of the
    loss guards, counted under `key` (one count per bet and per kind of loss sale). Any miss starts it again.
    cf = (checks, span, gap) from sl_confirm_params / hedge_confirm_params (#228 PR5/PR6); None = the constants."""
    checks, span, gap = cf or (SL_CHECKS, SL_SPAN, SL_GAP)
    streak = MINE.setdefault("sl_streak", {})
    seen = streak.get(key) or []
    if not hit:
        streak.pop(key, None)
        return False, why
    if seen and now - seen[-1] > gap:
        seen = []
    seen = (seen + [now])[-20:]
    streak[key] = seen
    if len(seen) < checks or now - seen[0] < span:
        return False, "waiting to confirm the drop"
    return True, ""


SL_MODES = ("tune", "allow")                      # the 'Never sell at a loss' choice was removed (Pete's decision, #479)
SL_MODE_SAY = {"tune": "Let it tune itself", "allow": "Allow (guarded)"}


def sl_norm(m):
    """A saved 'Selling at a loss' value as one of SL_MODES, or None when it is not one. The retired 'never' (saved on
    any device before that choice was removed) reads as 'tune': never a crash, and never silently 'allow'."""
    if m == "never":
        return "tune"
    return m if m in SL_MODES else None


def sl_mode():
    """Settings › Cash out › Selling at a loss (#228 PR5): 'tune' (the default: the stop-loss sells only in a league whose
    own record turned it on, `sl_allowed`) or 'allow' (the old switch on: every guard still holds). The retired 'never'
    reads as 'tune' (sl_norm). A setting saved before this (only the old on/off `stop_loss`) reads as 'allow' when it was
    on, else 'tune'; anything unreadable reads that way too."""
    m = sl_norm(CFG.get("stop_loss_mode"))
    if m:
        return m
    return "allow" if CFG.get("stop_loss") is True else "tune"


def sl_sync(cfg, incoming):
    """Applies a settings message's 'Selling at a loss' to `cfg` (the watcher's copy of the phone's or web app's
    settings, the web app's own save). A valid stop_loss_mode wins and the old switch is kept in step (on only for
    Allow); a retired 'never' from an older phone or saved file becomes 'tune'. A message without one (an older phone or
    page that only knows the on/off switch, or a phone with no control for it, which sends None) may only make it
    STRICTER: 'off' turns Allow into Let it tune itself; 'on' is ignored, so a stale old switch can never undo Let it
    tune itself."""
    m = sl_norm(incoming.get("stop_loss_mode"))
    if m:
        cfg["stop_loss_mode"] = m
        cfg["stop_loss"] = m == "allow"
        return
    if incoming.get("stop_loss") is False:
        cur = sl_norm(cfg.get("stop_loss_mode"))
        cur = cur if cur else ("allow" if cfg.get("stop_loss") is True else "tune")
        cfg["stop_loss_mode"] = "tune" if cur == "allow" else cur
        cfg["stop_loss"] = False


def sl_allowed(tickers):
    """Whether the stop-loss may sell this combo below what it cost (every guard still has to hold): 'allow' = yes;
    'tune' = only with self-tuning on and this league's OWN record having turned `sl_auto` on (never borrowed, off
    while its brake holds). Off on any error."""
    m = sl_mode()
    if m == "allow":
        return True
    if m != "tune" or not knob_switch_on():
        return False
    try:
        k, chain = _knob_bet_chain(tickers)
        v, g = knob_live_value("sl_auto", k, chain, knob_state_cached(), {}, time.time())
        return v == 1 and g == k
    except Exception as err:
        _knob_err("the stop-loss switch's own record", err)
        return False


def _knob_err(what, err):
    if time.time() - KNOB_PRM_ERR["at"] > 600:
        KNOB_PRM_ERR["at"] = time.time()
        print(f"self-tuning: {what} unreadable, using the starting ones:", type(err).__name__, err)


def _knob_nums(names, starts, tickers):
    """Self-tuning's live values for a few count/time knobs of a bet's league (the starts while the switch is off,
    nothing is learned, the league is braked, or on any error)."""
    if not knob_switch_on():
        return starts
    try:
        k, chain = _knob_bet_chain(tickers)
        st, now = knob_state_cached(), time.time()
        out = []
        for n, s0 in zip(names, starts):
            if n not in knob_live_names():                    # a watch-only knob (the hedge's lock-in numbers): its start
                out.append(s0)
                continue
            v, _ = knob_live_value(n, k, chain, st, {}, now)
            out.append(v if _knob_valid(n, v) and v is not None else s0)
        return tuple(out)
    except Exception as err:
        _knob_err("the confirmation counts", err)
        return starts


def sl_confirm_params(tickers):
    """(checks, span, gap) a loss sale must hold for, for this bet's league (#228 PR5: split from the hedge's)."""
    return _knob_nums(("sl_checks", "sl_span", "sl_gap"), (SL_CHECKS, SL_SPAN, SL_GAP), tickers)


def hedge_confirm_params(tickers):
    """(checks, span, gap) an auto-hedge must hold for (#228 PR6: its own numbers, starting at the loss guards')."""
    return _knob_nums(("hedge_checks", "hedge_span", "hedge_cgap"), (HEDGE_CHECKS, HEDGE_SPAN, HEDGE_CGAP), tickers)


def stop_loss_check(t, h, now=None, also=True, key=None):
    """The guard for selling a combo at a loss (the stop-loss switch, and the learned loss cut), called once per
    auto cash-out check: (ready, why not). Every pick already playing must have a fresh feed; one of them must pass
    every guard; `also` (the caller's own trigger, e.g. 'the combo is under the learned cut-off') must hold too; and
    all that must have held on SL_CHECKS checks in a row spanning SL_SPAN seconds (counted under `key`, default
    the combo). Any miss starts the count again."""
    now = now or time.time()
    need = [(side, tk) for (side, tk), _ in h.get("need") or []]
    pr = stoploss_params([tk for _, tk in need])
    hit, why = False, "no pick playing"
    for side, tk in need:
        pre = (h.get("pre_of") or {}).get(tk)
        ch = (h.get("ch_of") or {}).get(tk)
        ok, w = stop_loss_leg(tk, side, pre, ch, pr, now)
        if w in ("no score feed", "score feed stale"):
            try:
                st = leg_start({"ticker": tk, "side": side}, {})
            except Exception:
                st = None
            if st is None or st.timestamp() <= now:
                hit, why = False, w                     # a game on (or maybe on) with no fresh score: never
                break
        if ok:
            hit = True
        elif not hit:
            why = w
    if hit and not also:
        hit, why = False, "not under the cut-off"
    return _sl_confirm(key or t, hit, why, now, sl_confirm_params([tk for _, tk in need]))


def single_pre(x):
    """A single bet's chance before its game: the last one seen before it started (kept while the app runs), else,
    for a game-winner, the saved pregame chance. None when unknown, and then a loss cut never fires."""
    v = (MINE.get("pre_single") or {}).get(x.get("t"))
    if v is None and x.get("kind") == "win":
        p = load_json(PREGAME, {}).get(x.get("t"))
        if p is not None:
            v = p if (x.get("side") or "yes") == "yes" else 1 - p
    return v


def cut_loss_single_check(x, loss, now=None):
    """The learned loss cut's guard for a single bet, spread or total, called once per auto cash-out check: the same
    guards as the stop-loss switch (late in the game by the league's learned share, a fresh score, not at a break, at
    least the league's learned fall below the pregame chance, under 50%) plus 'under the cut-off', all held on 3+
    checks over 3+ minutes. Returns (ready, why not)."""
    now = now or time.time()
    leg = _score_leg(x["t"], x.get("kind") or "win", x.get("side") or "yes", x.get("sport") or "")
    q = x.get("chance")
    ok, why = stop_loss_leg(leg["ticker"], leg["side"], single_pre(x), q, stoploss_params([x["t"]]), now,
                            watch=(x["t"], x.get("side") or "yes"))    # (#316) the break evidence is the held market's
    if ok and not (loss and q is not None and q <= loss):
        ok, why = False, "not under the cut-off"
    return _sl_confirm("cut:" + x["t"], ok, why, now, sl_confirm_params([x["t"]]))


def note_cut_held(t, label, why, guard, hedge=False):
    """A learned loss cut (or, with hedge=True, an auto-hedge) that the guards held back: logged once per bet and
    reason (for Results › Selling)."""
    if len(MINE.setdefault("cut_told", {})) > 500:
        MINE["cut_told"].clear()
    told = MINE["cut_told"].setdefault(("hedge:" if hedge else "") + t, set())
    if not guard or guard in told:
        return
    told.add(guard)
    log_decision(dict({"combo": label, "ticker": t, "why": why, "result": "held", "guard": guard},
                      **({"hedge": True} if hedge else {})))


# ---------------------------------------------------------------- auto-hedge, guarded (issue #27)
# Auto-hedge (with Auto cash-out on) buys the other side of a combo's last game instead of an already-chosen sale.
# Before it buys, all of these must hold: the last game is in play on a fresh score (not missing or stale), not at
# halftime or a break, the hedge locks in at least what the combo cost, and all that held on 3+ checks in a row over
# 3+ minutes (the same count as the loss guards). Then the order book is read again and the sums are redone on that
# price. While it's confirming, the sale waits; if any other guard fails, it cashes out as if auto-hedge were off.
HEDGE_GAP = 0.06                                   # the widest bid/ask gap on the hedge side it will buy into
HEDGE_LOCK_COST = 1.0                              # a hedge must lock in at least this x what the combo cost
HEDGE_LOCK_SHARE = 0.95                            # "Hedge instead" on: hedge when it locks in 95%+ of the cash-out
HEDGE_LOCK_EXTRA = 0.5                             # ...off: only when it locks in $0.50+ more than the cash-out
HEDGE_CHECKS, HEDGE_SPAN, HEDGE_CGAP = SL_CHECKS, SL_SPAN, SL_GAP   # its own confirmation, starting at the loss guards'


def hedge_guard(t, h, hg, now=None):
    """The auto-hedge guards for combo `t` with hedge `hg` (from hedge_for), called once per check where the hedge
    beats the cash-out: (ready, why not). Shares the loss guards' fresh-score and confirmation helpers."""
    now = now or time.time()
    need = h.get("need") or []
    hit, why = False, "not down to one pick"
    tks = [tk for (_, tk), _ in need]
    if len(need) == 1:
        (side, tk), _ = need[0]
        sc, why = fresh_live_score(tk, side, now)
        hit = sc is not None
        if hit and at_break(sc) and not break_ok(tk, side, sc, now, "hedge"):
            hit, why = False, "halftime or a break"
        if hit and hg["locked"] < hedge_lock_cost(tks) * h["cost"]:
            hit, why = False, "wouldn't lock in what you paid"
    ready, why = _sl_confirm("hedge:" + t, hit, why, now, hedge_confirm_params(tks))
    return ready, ("waiting to confirm" if why == "waiting to confirm the drop" else why)


def hedge_fresh(t, h, whole):
    """Re-read the hedge side's order book right before buying and redo the sums on that price: (hedge, '') when it
    still beats the cash-out, fits the cap and locks in at least the combo's cost, else (None, why not)."""
    hg = hedge_for(t)
    bk = book_depth(hg["ticker"], max_age=0) if hg and hg.get("n") else None
    if not bk or not bk.get("ask"):
        return None, "no fresh price for the hedge"
    if bk.get("spread") is None or bk["spread"] > HEDGE_GAP + 1e-9:
        return None, "hedge side's order book too thin"
    hg = hedge_for(t, price=bk["ask"])
    if not hg or not hg.get("n"):
        return None, "no fresh price for the hedge"
    tks = [tk for (_, tk), _ in h.get("need") or []]
    if hg["cost"] > hedge_cap_now():
        return None, "over the hedge cap at the fresh price"
    if not hedge_beats(hg, whole, tks):
        return None, "no longer beats the cash-out at the fresh price"
    if hg["locked"] < hedge_lock_cost(tks) * h["cost"]:
        return None, "wouldn't lock in what you paid at the fresh price"
    return hg, ""


def hedge_beats(hg, whole, tickers=None):
    """Whether hedging locks in enough compared with the whole cash-out offer `whole` (#228 PR6: the 95% share is
    self-tuning's for the combo's league while the switch is on; the constant otherwise)."""
    if CFG.get("prefer_hedge", True):
        share = _knob_nums(("hedge_lock_share",), (HEDGE_LOCK_SHARE,), tickers)[0] if tickers else HEDGE_LOCK_SHARE
        return hg["locked"] >= whole * share
    return hg["locked"] >= whole + HEDGE_LOCK_EXTRA


HEDGE_MIN_N = 30                                   # recorded hedge decisions a group needs before the judge steps
HEDGE_SEEN = {}                                    # ticker -> when last recorded (one row per combo per 10 minutes)


def hedge_seen_note(t, h, hg, whole):
    """The hedge judge's evidence (#228 PR6, watch-only, never raises, never fetches): each time auto cash-out weighs
    a hedge against a due sale, what the hedge would cost and lock in, the whole cash-out offer, the combo's cost, your
    cap and 'Prefer hedging', and whether the last game was in play on a fresh score and not at a break (the guards a
    hedge can never skip). One row per combo per 10 minutes, in `hedge_seen`."""
    try:
        now = time.time()
        if not STORE.get("db") or now - HEDGE_SEEN.get(t, 0) < 600:
            return
        HEDGE_SEEN[t] = now
        if len(HEDGE_SEEN) > 2000:
            HEDGE_SEEN.clear()
        need = h.get("need") or []
        ok = False
        if len(need) == 1:
            (side, tk), _ = need[0]
            sc, _ = fresh_live_score(tk, side, now)
            ok = sc is not None and not at_break(sc)
        try:
            cap = float(CFG.get("hedge_cap", 100))
        except (TypeError, ValueError):
            cap = 100.0
        if not STORE.get("hseen_ok"):
            store_x("create table if not exists hedge_seen(ts real, ticker text, league text, whole real, locked real, "
                    "hcost real, cost real, cap real, prefer int, ok int)")
            store_x("create index if not exists hedge_seen_t on hedge_seen(ts)")
            STORE["hseen_ok"] = bool(store_rows("select name from sqlite_master where type='table' and name='hedge_seen'"))
        store_x("insert into hedge_seen(ts, ticker, league, whole, locked, hcost, cost, cap, prefer, ok) "
                "values(?,?,?,?,?,?,?,?,?,?)",
                (now, t, _knob_sale_league(t, {}), round(whole, 2), round(float(hg["locked"]), 2),
                 round(float(hg["cost"]), 2), round(float(h.get("cost") or 0), 2), cap,
                 int(bool(CFG.get("prefer_hedge", True))), int(ok)))
    except Exception as err:
        if time.time() - BRK_ERR["hedge"] > 600:
            BRK_ERR["hedge"] = time.time()
            print("hedge record:", type(err).__name__, err)


def break_watch_held():
    """Break episodes for every live pick of the combos you hold (watch-only, from cached scores and prices)."""
    try:
        now = time.time()
        for h in list((MINE.get("hold") or {}).values()):
            for (side, tk), _ in h.get("need") or []:
                sc = leg_score({"ticker": tk, "side": side})
                if sc and sc.get("state") == "in":
                    break_watch(tk, side, sc, now)
                else:
                    BRK_EP.pop((tk, side or "yes"), None)
    except Exception as err:
        print("break episodes:", type(err).__name__, err)


def hedge_lock_cost(tickers):
    """A hedge must lock in at least this x the combo's cost (never under 1: a hedge never locks in a loss)."""
    return max(1.0, _knob_nums(("hedge_lock_cost",), (HEDGE_LOCK_COST,), tickers)[0])


def hedge_cap_now():
    """The most one auto-hedge may spend: your setting; with self-tuning on, any raise the system made on evidence (up
    to $150, never lowering yours, your own value while any league's brake holds: knob_cap). Unreadable: $100."""
    try:
        pete = float(CFG.get("hedge_cap", 100))
    except (TypeError, ValueError):
        pete = 100.0
    if not knob_switch_on():
        return pete
    try:
        return float(knob_cap("hedge_cap", pete=pete, st=knob_state_cached()))
    except Exception as err:
        _knob_err("the hedge cap's raise", err)
        return pete


def hedge_unsure(t):
    """A hedge on this combo whose outcome is unknown: marked 'check', never retried, and auto cash-out leaves the
    combo alone until you look. A mark this process couldn't write to the file still counts (kept in memory)."""
    return bool((load_json(HEDGES, {}).get(t) or {}).get("check")) or t in _HEDGE_UNSURE_MEM


_HEDGE_UNSURE_MEM = sys.modules.setdefault("_combo_hedge_mem", type(sys)("_combo_hedge_mem")).__dict__.setdefault("d", {})


def hedges_update(combo, **fields):
    """Read-change-write one combo's entry in combo_hedges.json under its file lock (the watcher and the web app
    both write it). A failed write is logged loudly and raised; a "check" mark is kept in memory first."""
    if fields.get("check"):
        _HEDGE_UNSURE_MEM[combo] = dict(fields)
    with file_lock(HEDGES):
        d = load_json(HEDGES, {})
        d[combo] = dict(d.get(combo) or {}, **fields)
        save_json(HEDGES, d, strict=True)
    if fields.get("check"):
        _HEDGE_UNSURE_MEM.pop(combo, None)


SWING_BASE = 0.35         # the risk weight per unit of a sport's swing (SWING), before the league's and Let it ride's
CHECKPOINT_LAM = 1.3      # between a slate's games, with a pick already won, the risk counts this much more


def swing_lambda(h):
    """How much the risk of holding counts, from the picks still to play: swingier sports (a one-goal hockey
    lead) count more; a game that's mostly played counts less (time left, square-rooted: half the game left
    is ~70% of the swing); between games of a slate combo, with a pick already won, a checkpoint counts more."""
    vols = []
    for (side, tk), _ in h.get("need") or []:
        sw = SWING.get(ticker_sport(tk) or "", 1.0)
        sc = leg_score({"ticker": tk, "side": side}) or {}
        if sc.get("state") == "in" and sc.get("frac") is not None:
            sw *= math.sqrt(max(sc["frac"], 0.02))
        vols.append(sw)
    lam = SWING_BASE * (sum(vols) / len(vols) if vols else 1.0)
    live = any(lv for _, lv, _ in h.get("legs_left") or [])
    checkpoint = not live and h.get("won_some") and not h.get("progressed")
    return (lam * CHECKPOINT_LAM, "checkpoint") if checkpoint else (lam, "")


GAME_SD = {"nhl": 2.4, "ahl": 2.5, "soccer": 1.9, "mls": 1.9, "epl": 1.9}      # final-margin spread (goals) for low scorers
SCORE_UNIT = {"nhl": (1, "goal"), "ahl": (1, "goal"), "soccer": (1, "goal"), "mls": (1, "goal"), "epl": (1, "goal"), "nfl": (7, "touchdown"),
              "ncaaf": (7, "touchdown"), "nba": (6, "6-0 run"), "ncaamb": (6, "6-0 run"), "ncaawb": (6, "6-0 run")}


def what_if(ticker, chance, side="yes"):
    """How this pick's chance would move on the next score either way: {'unit', 'up', 'down'} or None.
    The current price already says how strong the lead is; a score shifts the margin by one unit against
    the spread of what's left (full-game spread x square root of the time left)."""
    code = ticker_sport(ticker) or ""
    if code not in SCORE_UNIT or chance is None or not 0.005 < chance < 0.995:
        return None
    sc = leg_score({"ticker": ticker, "side": side}) or {}
    if sc.get("state") != "in" or sc.get("frac") is None:
        return None
    g, unit = SCORE_UNIT[code]
    sd = (GAME_SD.get(code) or MARGIN_SD.get(code) or 12.0) * math.sqrt(max(sc["frac"], 0.02))
    nd = statistics.NormalDist()
    z = nd.inv_cdf(chance)
    return {"unit": unit, "up": round(nd.cdf(z + g / sd), 4), "down": round(nd.cdf(z - g / sd), 4)}


def recap(day=None):
    """Yesterday in one card: the panel's bets, combos that finished, and the streak of days up."""
    day = day or (dt.datetime.now(PACIFIC) - dt.timedelta(days=1)).date().isoformat()
    out = {"day": day, "bets": [], "pl": 0.0, "won": 0, "lost": 0}
    p = {"items": day_items(day)}
    for c in p["items"]:
        if c.get("result"):
            out["bets"].append({"what": bet_text(c), "kind": c["kind"],
                                "pl": c["pl"], "chance": c["chance"]})
    if STORE["db"]:
        start = dt.datetime.fromisoformat(day).replace(tzinfo=PACIFIC).timestamp()
        mine = {c.get("market") for c in (p or {}).get("items", []) if c.get("market")}
        for r in store_rows("select combo, cost, pays, back, status, legs from bets where settled >= ? and settled < ?",
                            (start, start + 86400)):
            if r["combo"] in mine:
                continue                               # a panel combo: already counted above
            got = r["back"] if r["status"] == "cashed" else r["pays"] if r["status"] == "won" else 0
            out["bets"].append({"what": f"Combo ({len(json.loads(r['legs'] or '[]'))} picks)", "kind": "combo",
                                "pl": round((got or 0) - r["cost"], 2), "status": r["status"]})
    out["pl"] = round(sum(b["pl"] for b in out["bets"]), 2)
    out["won"] = sum(1 for b in out["bets"] if b["pl"] > 0)
    out["lost"] = sum(1 for b in out["bets"] if b["pl"] <= 0)
    if out["bets"]:
        out["best"] = max(out["bets"], key=lambda b: b["pl"])
        out["worst"] = min(out["bets"], key=lambda b: b["pl"])
        sure = [b for b in out["bets"] if b.get("chance") and b["chance"] >= 0.7 and b["pl"] < 0]
        long_ = [b for b in out["bets"] if b.get("chance") and b["chance"] < 0.45 and b["pl"] > 0]
        out["note"] = ("A likely one missed: " + sure[0]["what"] + ". That happens about a third of the time at 70%."
                       if sure else "A long shot came in: " + long_[0]["what"] + "." if long_ else "")
    streak, d = 0, dt.date.fromisoformat(day)
    for _ in range(30):                                # days up in a row, ending yesterday
        q = day_items(d.isoformat())
        pl = sum(c.get("pl") or 0 for c in q if c.get("result"))
        if not q or pl <= 0:
            break
        streak += 1
        d -= dt.timedelta(days=1)
    out["streak"] = streak
    return out


TP_MIN_GAIN = 1.25       # take profit only with at least 25% over what you paid
TRAIL_ARM, TRAIL_DROP = 0.60, 0.20   # lock in: armed once the offer reached 60% of the payout (and 1.5x cost)
TRAIL_ARM_COST = 1.5     # ...and 1.5x what you paid
TRAIL_FLOOR = 1.1        # lock in only sells at 1.1x what you paid or more
EXIT_Q_MIN = 0.5         # smart sell takes a profit only while the pick (or combo) is still at least this likely
EXIT_EST_SMART = 0.95    # a combo's steady estimate counts as up to 1/0.95 of itself against smart sell's line
EXIT_EST_TP = 0.9        # ...and up to 1/0.9 against take profit's (Kalshi's real offer is checked before any sale)
CUT_ACCEPT = 0.02        # a learned loss cut on a combo accepts an offer of at least 2% of what you paid
# These numbers are named (not written inline) so the knob registry (issue #228) can list them; same values.
# From #228 PR3 exit_policy also takes each one in `prm` (below); without it, it uses these, so every caller that
# passes nothing decides exactly as before.
EXIT_POLICY_VERSION = 2


def exit_policy(s, prm):
    """Smart sell's decision, in one place (issue #137: Smart Sell runs it, Smart Buy simulates it). Pure: it reads
    nothing but its two arguments (and the fixed constants above), so the live sellers and the simulator get the
    same answer for the same state.
    s: kind 'combo' or 'single'; value = what selling now brings (a combo: the steady estimate, live chance x payout
       x Kalshi's discount; a single: contracts x (bid - fee)); real = a combo's real Kalshi offer for the whole
       combo (0 = none); peak = the highest value seen so far (including now); pays = payout if it wins; cost = what
       was paid; q = the live chance; live = a game under way.
    prm: tp = take-profit share of the payout (0 = off); smart = smart sell is on (Let it ride isn't Ride it out),
       with lam = the risk weight (swing x league x Let it ride), floor = the league's profit floor (x cost),
       loss = the league's own learned loss cut (None = never), checkpoint = between a slate's games; cut_ok = every
       loss guard held; trail = lock in after a run-up.
       Self-tuning's numbers (#228 PR3), each optional and defaulting to the constant above: q_min (EXIT_Q_MIN),
       est_smart / est_tp (the estimate allowances), tp_min (TP_MIN_GAIN), trail_arm / trail_arm_cost / trail_drop /
       trail_floor (lock in), cut_accept (CUT_ACCEPT).
    Returns {'sell', 'reason', 'threshold' (the least to accept), 'floor' (smart sell's hold value, shown on Live)}."""
    combo = s.get("kind") == "combo"
    val, real, peak = s["value"], s.get("real") or 0.0, s["peak"]
    P, cost, q, live = s["pays"], s["cost"], s["q"], s["live"]
    hits = []
    g = prm.get
    tp = g("tp") or 0
    if tp:
        f = max(tp * P, g("tp_min", TP_MIN_GAIN) * cost)
        if (max(val / g("est_tp", EXIT_EST_TP), real) if combo else val) >= f:
            hits.append(("take profit", f))
    floor2 = 0.0
    if g("smart"):
        lam = prm["lam"]
        floor2 = max(q * P - lam * P * math.sqrt(max(q * (1 - q), 0)), prm["floor"] * cost)
        if q >= g("q_min", EXIT_Q_MIN) and (max(val / g("est_smart", EXIT_EST_SMART), real) if combo else val) >= floor2:
            hits.append(("checkpoint" if g("checkpoint") else "smart", floor2))
        loss = g("loss")
        if loss and live and q <= loss and g("cut_ok") and (combo or val > 0):
            hits.append(("cut loss", g("cut_accept", CUT_ACCEPT) * cost if combo else 0.0))   # learned, every guard held
    if hits:
        why, thr = min(hits, key=lambda x: x[1])
        return {"sell": True, "reason": why, "threshold": thr, "floor": floor2}
    t_floor = g("trail_floor", TRAIL_FLOOR)
    if g("trail") and peak >= max(g("trail_arm", TRAIL_ARM) * P, g("trail_arm_cost", TRAIL_ARM_COST) * cost) \
            and val <= (1 - g("trail_drop", TRAIL_DROP)) * peak and (max(val, real) if combo else val) >= t_floor * cost:
        return {"sell": True, "reason": "lock in", "threshold": t_floor * cost, "floor": floor2}
    return {"sell": False, "reason": None, "threshold": 0.0, "floor": floor2}


def take_profit_reason(t, h, cut_ok=False):
    """Whether Pete's profit rules say sell this combo now: "take profit" when the offer reaches his
    take-profit % of the payout, or "lock in" when, after a big run-up, it has fallen 20% from its
    high but is still a clear profit. A learned "cut loss" also needs `cut_ok`: the loss guards held
    (stop_loss_check under "cut:<ticker>", run once per check by auto_sell_now); without it, never. Tracked on a steady estimate (live chance x payout x Kalshi's
    usual discount) so a one-off quote can't fake a high or a drop; the real offer is checked before
    any sale. Returns (reason, the least whole-combo offer to accept) or (None, 0)."""
    if not h or h.get("left", 1) <= 0 or not h.get("pays"):
        return None, 0.0
    live = any(lv for _, lv, _ in h.get("legs_left") or [])
    est = kalshi_discount(live) * h["p"] * h["pays"]
    o = MINE["cash"].get(t) or {}
    real = o["offer"] / max(o.get("frac", 1.0), 0.01) if o.get("offer") and o.get("rfq") not in (None, "estimate") \
        and time.time() - o.get("at", 0) <= offer_life() else 0.0
    peak = MINE.setdefault("peak", {})
    peak[t] = max(peak.get(t, 0.0), est)
    tks = [tk for (_, tk), _ in h.get("need") or []]
    prm = {"tp": float(CFG.get("take_profit") or 0) / 100, "trail": CFG.get("lock_trail", True), "cut_ok": cut_ok,
           **knob_exit_prm(tks)}                      # self-tuning's numbers (#228 PR3): {} while it is off
    pr = smart_params(tks)
    rl = ride_lam()
    if CFG.get("smart_sell", True) and rl is not None:  # nimble: lock in when that beats the risk of holding
        lam, why_note = swing_lambda(h)
        lam *= pr["lam"] * rl
        prm.update(smart=True, lam=lam, floor=pr["floor"], loss=pr["loss"], checkpoint=bool(why_note))
    d = exit_policy({"kind": "combo", "value": est, "real": real, "peak": peak[t], "pays": h["pays"],
                     "cost": h["cost"], "q": h["p"], "live": live}, prm)
    return (d["reason"], d["threshold"]) if d["sell"] else (None, 0.0)


def cash_nudge(t, h, tp=None):
    """Whether a "time to cash out" alert (the Live toast, the moment bar, a Do now card, the phone's push) may go out
    for this live combo (#210). Alerts only: it reads, never sells, and auto cash-out does not look at it. All of:
      - smart sell's own rule says sell now (exit_policy via take_profit_reason; tp = its answer when already worked
        out this refresh), not the older Let it ride plan, which also says "sell" for a long shot on an estimate;
      - a real Kalshi offer that is still fresh (never the watcher's estimate);
      - that offer is at least what was paid, and at least 97% of the line the rule sells at;
      - one of the games still to play is under way (between games nothing changes, so nothing to say).
    Returns {'why', 'offer' (whole combo)} or None."""
    if not h or h.get("left", 1) <= 0 or not h.get("pays"):
        return None
    why, floor = tp if tp is not None else take_profit_reason(t, h)
    if not why:
        return None
    o = MINE["cash"].get(t) or {}
    if o.get("rfq") in (None, "estimate") or not o.get("offer") or not fresh_offer(t):
        return None
    whole = o["offer"] / max(o.get("frac", 1.0), 0.01)
    if whole < (h.get("cost") or 0) or whole < 0.97 * (floor or 0):
        return None
    if not any(lv for _, lv, _ in h.get("legs_left") or []):
        return None
    return {"why": why, "offer": round(whole, 2)}


def auto_sell_now(plan):
    """Auto cash-out (Settings, off by default): sells what the plan says to cash out, by itself,
    the same advice the card shows as Cash out. That already means a pick has won and Kalshi's
    offer is at least the Let it ride price for waiting another game; both are checked again here.
    Uses Kalshi's cash-out offers (the only way it buys combos back), so it runs while the planner
    is open. Returns the messages to send."""
    if not (CFG.get("auto_sell") and plan and can_trade()) or MINE.get("busy") or trading_paused():
        return []                                      # Pause (read fresh) stops every automatic sale; only Pete's own tap sells (#245)
    out = []
    if sell_held(out):                                 # Kalshi is refusing sales: don't ask again every pass (#134)
        return out
    MINE["busy"] = True
    began = time.time()
    try:
        cands = [(t, f, "plan") for t, f in sorted(plan["acts"].items(), key=lambda x: -x[1]) if f]
        asked = MINE.setdefault("tp_asked", {})
        cands = [c for c in cands if not hands_off(c[0])]
        break_watch_held()                                # break episodes for the judge (watch-only, #228 PR5)
        mode = sl_mode()                                  # Settings › Selling at a loss (#228 PR5)
        sl_ready = {}                                     # the stop-loss switch: only once every guard holds
        for t, h in list(MINE["hold"].items()):
            if mode == "allow" or sl_allowed([tk for (_, tk), _ in h.get("need") or []]):
                sl_ready[t] = stop_loss_check(t, h)[0]
        cut_ready = {}                                    # the learned loss cut: the same guards, counted apart
        if CFG.get("smart_sell", True) and ride_lam() is not None:
            for t, h in list(MINE["hold"].items()):
                loss = smart_params([tk for (_, tk), _ in h.get("need") or []])["loss"]
                if not loss:
                    continue
                trig = any(lv for _, lv, _ in h.get("legs_left") or []) and h["p"] <= loss
                cut_ready[t], gw = stop_loss_check(t, h, also=trig, key="cut:" + t)
                if trig and not cut_ready[t]:
                    note_cut_held(t, h.get("label", t), "cut loss", gw)
        for t, h in list(MINE["hold"].items()):          # Pete's profit rules, on every live combo
            if any(c[0] == t for c in cands) or hands_off(t):
                continue
            why, floor = take_profit_reason(t, h, cut_ready.get(t, False))
            if why and time.time() - asked.get(t, 0) >= 90:
                asked[t] = time.time()
                cands.append((t, 1.0, why))
        for t, f, why in cands:
            if time.time() - began > AUTO_CASH_BUDGET:
                break                                     # one pass stays short: the rest wait for the next check
            if manual_selling(t):
                log_decision({"combo": (MINE["hold"].get(t) or {}).get("label", t), "ticker": t, "why": why, "result": "skipped",
                              "note": "your own Cash out tap is selling this right now (#400); checked again next round"})
                continue                                  # Pete's tap has it (another process): never two sales at once
            h = MINE["hold"].get(t)
            if not h:
                COMBO_WAIT.pop(t, None)                   # sold elsewhere or settled: nothing left to wait on
            if hedge_unsure(t) or rfq_unsure(t, "sell"):
                continue                                  # a hedge or cash-out with an unknown outcome: hands off until checked
            o = fresh_offer(t) if why == "plan" else (MINE["cash"].get(t) or {"offer": 0.01, "frac": 1.0, "rfq": "estimate"}) if h else None
            if not (f and h and o) or t in MINE.get("selling", set()):
                continue
            if why == "plan":
                if not h.get("won_some"):
                    continue
                thr = wait_threshold(t)
            else:
                thr = take_profit_reason(t, h, cut_ready.get(t, False))[1]
                if not thr:
                    continue
            slip = knob_auto_slip([tk for (_, tk), _ in h.get("need") or []]) if why != "plan" else AUTO_CASH_SLIP
            held_why = combo_wait_why(t, h, f, thr * (1.0 if why == "plan" else slip), kind=why)
            if held_why:
                continue                                  # buyers backed out: waiting for the game or price to change
            clock = bool((COMBO_WAIT.get(t) or {}).get("clock_now"))   # #396: this try is the loss-cut clock retry
            first_offer = (COMBO_WAIT.get(t) or {}).get("first") if (COMBO_WAIT.get(t) or {}).get("cutting") else None   # only a loss cut's own first offer (not a profit round's)
            if why == "plan" and o["offer"] / max(o.get("frac", 1.0), 0.01) < thr:
                continue
            if why != "plan" and o.get("rfq") not in (None, "estimate") and time.time() - o.get("at", 0) <= offer_life() \
                    and o["offer"] / max(o.get("frac", 1.0), 0.01) < slip * thr:
                if clock:
                    log_decision({"combo": h.get("label", t), "ticker": t, "kind": "combo", "result": "skipped",
                                  "why": "loss-cut clock retry: the offer is under the smart-sell line",
                                  "clock_retry": COMBO_WAIT[t].get("clock_n"), "offer": round(o["offer"], 2)})
                continue                                  # a real offer just came in below the line
            if why != "plan" and (o.get("rfq") in (None, "estimate") or time.time() - o.get("at", 0) > offer_life()):
                o = dict(o, rfq="estimate")
            if f < 1 or o.get("frac", 1.0) < 1 or o.get("rfq") == "estimate":   # the Pi only estimates
                o = get_cash_offer(t, f)
                MINE["cash"][t] = o
                if not o.get("offer") or o["offer"] / max(o.get("frac", 1.0), 0.01) < slip * thr:
                    if clock:
                        log_decision({"combo": h.get("label", t), "ticker": t, "kind": "combo", "result": "skipped",
                                      "why": "loss-cut clock retry: " + ("no fresh offer came in" if not o.get("offer")
                                                                         else "the offer is under the smart-sell line"),
                                      "clock_retry": COMBO_WAIT[t].get("clock_n"), "offer": round(o.get("offer") or 0, 2)})
                    continue
            acct = fetch_account(max_age=0, every_league=True)[0]
            held = {a["ticker"]: a for a in (acct or [])}
            a = held.get(t)
            if not a or a.get("status") != "pending" or a.get("pays", 0) < o.get("contracts", 0) - 0.01:
                if clock:                       # fail closed, and say so (#396)
                    log_decision({"combo": h.get("label", t), "ticker": t, "kind": "combo", "result": "skipped",
                                  "why": "loss-cut clock retry: account unreadable" if acct is None else
                                         "loss-cut clock retry: combo gone or reduced", "clock_retry": COMBO_WAIT[t].get("clock_n")})
                drop_cash(t)                    # already sold (by you, the Pi or the phone): leave it
                continue
            rec = {"combo": h["label"], "ticker": t, "offer": round(o["offer"], 2), "cut_off": round(thr, 2), "why": why,
                   "chance": round(h["p"], 4), "cost": round(h["cost"], 2), "pays": h["pays"],
                   "picks_left": [round(c, 3) for c, _, _ in h.get("legs_left") or []],
                   "frac": round(o.get("frac", 1.0), 3), "kind": "combo", "side": "yes",
                   "live": any(lv for _, lv, _ in h.get("legs_left") or [])}
            try:                                      # (#300) log only: the estimate smart sell held this sale against
                rec["disc"] = round(kalshi_discount(rec["live"]), 4)
                rec["est"] = round(rec["disc"] * h["p"] * h["pays"] * o.get("frac", 1.0), 2)
            except Exception:
                pass
            if auto_cap_reached():
                log_decision(dict(rec, result="skipped", why="daily cap reached"))
                if MINE.get("cap_told") != dt.date.today().isoformat():
                    MINE["cap_told"] = dt.date.today().isoformat()
                    out.append(f"🤖 Auto cash-out reached today's cap of {auto_cap_limit()} sales. "
                               f"{h['label']} qualifies too: open the planner to cash it out yourself.")
                continue
            net, fee_note = combo_sale_net_info(o)        # #382/#383: below cost AFTER the selling fee (switch combo_sell_fee)
            rec["net"] = round(net, 2)                    # log net next to gross (rec["offer"])
            if fee_note:
                rec["fee_note"] = fee_note                # fee model off, or no contracts: judged on the gross offer
            gross_below = o["offer"] < h["cost"] * o.get("frac", 1.0) - 0.005
            below = net < h["cost"] * o.get("frac", 1.0) - 0.005
            if below and why != "cut loss" and not sl_ready.get(t):
                log_decision(dict(rec, result="skipped", why="below what you paid"))
                continue
            if below and why != "cut loss" and gross_below:   # only a gross-below-cost sale is a stop-loss sale
                rec["stop_loss"] = True
                rec["sl_mode"] = mode
            hg = hedge_for(t) if CFG.get("auto_hedge") and not clock and not restriction_holding("buy") else None   # a hedge is a buy (#134)
            whole = o["offer"] / max(o.get("frac", 1.0), 0.01)
            tks_ = [tk for (_, tk), _ in h.get("need") or []]
            better = hedge_beats(hg, whole, tks_) if hg and hg.get("n") else False
            if hg and hg.get("n"):
                hedge_seen_note(t, h, hg, whole)          # the hedge judge's evidence (watch-only, #228 PR6)
            if better:
                cap_ = hedge_cap_now()
                if hg["cost"] > cap_:
                    rec["hedge_skipped"] = f"hedge would cost {money(hg['cost'])}, over the {money(cap_)} cap"
                    better = False
            if better:
                ready, gw = hedge_guard(t, h, hg)
                if ready:
                    hg, gw = hedge_fresh(t, h, whole)
                    ready = hg is not None
                if not ready:
                    if gw == "waiting to confirm":
                        continue                # the sale waits while the hedge is confirmed (3+ checks, 3+ minutes)
                    note_cut_held(t, h["label"], why, gw, hedge=True)
                    rec["hedge_skipped"] = "held back by the guards: " + gw
                    if below and guards_on() and gw in ("score feed stale", "halftime or a break"):
                        # a learned wider score age / break rule opens the LOSS sale only; never sell below cost while a
                        # better hedge is blocked by that same staleness or break (review P1): wait for a fresh read
                        log_decision(dict(rec, result="skipped", why="a better hedge waits for a fresh score"))
                        continue
                else:
                    if t in MINE["cash"]:
                        drop_cash(t)            # not selling: release the cash-out request
                    msg = place_hedge(t, hg=hg, auto=True)
                    ok = msg.startswith("✅")
                    unsure = msg.startswith("⚠️")
                    log_decision(dict(rec, result="hedged" if ok else "hedge check" if unsure else "hedge failed",
                                      hedge_cost=round(hg["cost"], 2), locked=round(hg["locked"], 2), note=msg[:140]))
                    if ok:
                        vs = ("more than" if hg["locked"] > whole + HEDGE_LOCK_EXTRA else "about the same as")
                        out.append(f"🤖 Auto-hedge (Let it ride: {ride_level()[0]}): locks in {vs} the "
                                   f"{money(whole)} cash-out, without the buyer's cut. " + msg)
                        continue
                    if unsure:
                        out.append("🤖 Auto-hedge: " + msg)
                        continue                # never retried, and no sale on top of a hedge that may have filled
            CASH_LAST.pop(t, None)
            # The sale's purpose (Pete, 2026-11-23: "It should only sell at a loss if that's a way to try to minimize
            # losses. Not when there's still an opportunity for it to get profit."): a sale whose offer was at or above
            # cost is taking a profit and never takes a fresh offer below cost; a loss cut (the learned cut or a guarded
            # stop-loss, already below cost) may go below cost, down to the line, and not under 97% of its first offer.
            cutting = gross_below and (why == "cut loss" or bool(rec.get("stop_loss")))   # a sale above gross cost is never a loss cut
            rec["purpose"] = "cut a loss" if cutting else "take a profit"
            if clock:
                rec["clock_retry"] = COMBO_WAIT[t].get("clock_n")
                if not cutting or why != "cut loss":         # #396: the clock is for loss cuts only (a profit reason, even a stop-loss on one, waits for a change)
                    log_decision(dict(rec, result="skipped", stop="clock retry is for loss cuts only",
                                      why="loss-cut clock retry: not a loss cut now"))
                    continue
                if not first_offer or o["offer"] < first_offer_floor(first_offer):   # the 97% guard holds across rounds
                    log_decision(dict(rec, result="skipped", stop="below 97% of the first offer", first_offer=first_offer,
                                      why="loss-cut clock retry: offer under 97% of the first offer"))
                    continue
            if cutting and first_offer and not clock and o["offer"] < first_offer_floor(first_offer):
                # review fix: the same 97%-of-the-first-offer floor holds for EVERY loss-cut round, also one started by a
                # game or price change, not only the timed retries
                log_decision(dict(rec, result="skipped", stop="below 97% of the first offer", first_offer=first_offer,
                                  why="loss-cut retry: offer under 97% of the first offer"))
                continue
            try:
                _CASH_CTX.auto = True                     # up to 10 tries, short pauses, one more ask (Pete, 2026-11-23)
                _CASH_CTX.line = thr * (1.0 if why == "plan" else slip) * o.get("frac", 1.0) or None   # retries' bar
                _CASH_CTX.cost_floor = None if cutting else h["cost"] * o.get("frac", 1.0)
                _CASH_CTX.cutting = cutting
                _CASH_CTX.first_offer = first_offer if cutting else None   # #396: EVERY loss-cut round keeps 97% of the episode's FIRST offer
                msg = accept_cash(t)
            finally:
                _CASH_CTX.auto, _CASH_CTX.line, _CASH_CTX.cost_floor, _CASH_CTX.cutting = False, None, None, False
                _CASH_CTX.first_offer = None
            info = CASH_LAST.pop(t, None) or {}
            result = "sold" if msg.startswith("✅") else "check" if msg.startswith("⚠️") else "failed"
            stop = info.get("stop") or {"sold": "sold", "check": "unknown"}.get(result, "")
            bkey = ("combo", round(f, 3))
            prev = COMBO_WAIT.get(t) or {}
            if result == "sold" and info.get("tries"):
                rec["offer"] = info["tries"][-1]["offer"]  # the price it really sold at (the first is kept as agreed)
            log_decision(dict(rec, result=result, note=msg[:140], stop=stop, slip=round(slip, 3),
                              round=(prev.get("total", 0) if prev.get("key") == bkey else 0) + 1,
                              retry_on=prev.get("why_now") if prev.get("key") == bkey else None,
                              **{k: info[k] for k in ("rounds", "tries", "agreed", "line", "floor", "asked_again", "ask_error",
                                                      "low_offer", "below_agreed") if k in info}))
            if result != "failed":
                COMBO_WAIT.pop(t, None)                   # a sale (or an unclear one, blocked by rule 8) starts over
                MINE.setdefault("combo_fail_told", {}).pop(t, None)
            if result == "check":                         # may or may not have sold: no "took the profit" words
                out.append("🤖 Auto cash-out: " + msg)
                continue
            if result == "failed" and stop in ACCOUNT_STOPS:
                continue                                  # logged above; calm: no push (nothing was at risk or sold)
            if result == "failed":
                wait = stop in COMBO_BACKOFF_STOPS
                if wait:                                  # re-tried when the game or the price changes, not on a clock
                    combo_wait_start(t, h, bkey, rec["offer"], info, thr * (1.0 if why == "plan" else slip),
                                     cutting=cutting and why == "cut loss", agreed=info.get("agreed"))
                note = combo_fail_note(h["label"], info, stop, wait, msg)
                told = MINE.setdefault("combo_fail_told", {})
                if time.time() - told.get(t, 0) >= COMBO_FAIL_TELL:
                    told[t] = time.time()                 # one note per combo an hour
                    out.append(note)
                continue
            lead = {"take profit": f"🤖 Take profit: the offer reached {CFG.get('take_profit')}% of the payout. ",
                    "lock in": "🤖 Locked in a profit: the offer fell 20% from its high. ",
                    "smart": "🤖 Took the profit: locking it in now beats the risk of holding. ",
                    "checkpoint": "🤖 Checkpoint: the early games came through, so it took the profit before the next ones. ",
                    "cut loss": "🤖 Cut a loss: in this league, selling a bet this far behind has done better than holding. "}.get(
                why, "🤖 Auto cash-out (Let it ride: " + ride_level()[0] + "). ")
            if rec.get("stop_loss"):
                lead = ("🤖 Stop-loss (tuned for this league): sold for less than you paid. In this league, selling a "
                        "combo this far behind late in a game has beaten holding. "
                        if mode == "tune" else
                        "🤖 Stop-loss (your Allow setting): late in the game a pick fell well below its pregame chance "
                        "and stayed there, so it sold for less than you paid. ")
            out.append(lead + msg)
            if msg.startswith("✅"):
                MINE.get("peak", {}).pop(t, None)
        try:
            out += smart_sell_singles()
        except Exception as err:
            print("smart sell (singles):", type(err).__name__, err)
    finally:
        MINE["busy"] = False
    return out


COMBO_BACKOFF_STOPS = ("cancelled", "failed", "no fresh offer", "offer too low", "out of time")   # clear failures only
# Not restoring the auto-sell order after these stops is deliberate: the contracts may already be gone (sold elsewhere, or
# the account was unreadable), and a resting sell on them is worse than none; the next pass re-places it if still held.
ACCOUNT_STOPS = ("account changed", "account unreadable")   # an auto round stopped before a retry: nothing more sold
ACCOUNT_STOP_WORDS = {"account changed": "this combo was already sold or reduced while auto cash-out was retrying, "
                                         "so it stopped and sold nothing more.",
                      "account unreadable": "Kalshi's account couldn't be read before a retry, so auto cash-out stopped "
                                            "and sold nothing more. It will check again on the next pass."}
COMBO_FAIL_TELL = 3600    # a combo's "nothing sold" note at most once an hour
# After a round where buyers backed out, the combo is tried again only when something real changes (Pete, 2026-11-23:
# "It should retry based on changes in the game, not some arbitrary number of minutes"): a score, a game going live or
# final, a break starting or ending, a pick decided, the combo's chance or the cached offer moving COMBO_RETRY_MOVE,
# or the smart-sell line moving that much. COMBO_RETRY_GAP is only a courtesy gap so one pass never asks Kalshi twice.
COMBO_RETRY_MOVE = 0.05   # 5% of the combo's value / offer / line, and at least:
COMBO_RETRY_MIN_P = 0.02  # 2 points of chance (a 5% move on a 10% chance is noise)
COMBO_RETRY_MIN_USD = 0.25  # 25 cents of offer or line
COMBO_RETRY_GAP = 5       # seconds
COMBO_WAIT = {}           # ticker -> {"key", "snap", "p", "offer", "line", "at", "total", "told", "why_now", + the #396 clock keys}
# #396 (Pete's decision): a stuck LOSS CUT (never a profit sale) is also retried on a clock, a safety valve for when
# nothing moves. Every bound still applies: Pause (auto_sell_now returns first), rule 8 (an unknown outcome is never
# retried), the 97%-of-the-FIRST-offer guard across rounds, the smart-sell line, and at most LOSSCUT_CLOCK_MAX of
# these clock tries per position (kept in memory; a restart or a sale starts it over).
LOSSCUT_CLOCK_SECS = 300  # 5 minutes after the last failed round or clock try
LOSSCUT_CLOCK_MAX = 6     # at most 6 clock tries per position (about 30 minutes), then it waits for a real change only


def combo_game_snap(h):
    """What the combo's games look like now: per pick still open, (state, its score, the other score, at a break),
    from the watcher's score feed (leg_score). None for a pick with no score."""
    out = []
    for (side, tk), _ in h.get("need") or []:
        try:
            sc = leg_score({"ticker": tk, "side": side})
        except Exception:                            # a score-feed hiccup never stops the pass
            sc = None
        out.append((tk, None if not sc else (sc.get("state"), sc.get("me"), sc.get("opp"), bool(sc.get("brk")))))
    return tuple(sorted(out, key=lambda x: x[0] or ""))


def _game_changed(a, b):
    """The open picks changed (one decided), or a game with a score in both looks different. A pick whose score
    dropped out of the feed (None) is not a change: a flickering feed must not open the gate."""
    da, db = dict(a or ()), dict(b or ())
    return set(da) != set(db) or any(da[k] is not None and db[k] is not None and da[k] != db[k] for k in da)


def combo_wait_start(t, h, key, offer, info, line, cutting=False, agreed=None):
    """A round failed: remember the game and the price, so the next try waits for one of them to change.
    #396: also whether it was a loss cut, the episode's FIRST offer (kept across rounds) and the clock tries used."""
    prev = COMBO_WAIT.get(t) or {}
    same = prev.get("key") == key
    total = (prev.get("total", 0) if same else 0) + 1
    last = ((info or {}).get("tries") or [{}])[-1].get("offer") or offer
    COMBO_WAIT[t] = {"key": key, "snap": combo_game_snap(h), "p": h.get("p") or 0.0,
                     "offer": (info or {}).get("low_offer") or last, "line": line, "at": time.time(), "total": total,
                     "cutting": bool(cutting), "first": (prev.get("first") if same and prev.get("cutting") and prev.get("first") else agreed),   # a profit round's offer is not a loss cut's first
                     "clock_n": prev.get("clock_n", 0) if same else 0, "clock_at": time.time()}


def _moved(a, b, least):
    a, b = a or 0.0, b or 0.0
    return abs(a - b) >= max(COMBO_RETRY_MOVE * max(abs(a), abs(b)), least)


def first_offer_floor(first):
    """#396: the least a loss cut's offer may be, measured from the episode's FIRST offer (97%, the same CASH_SLIP guard)."""
    return CASH_SLIP * first


def _clock_due(w, kind):
    """#396: '' unless this wait is a stuck loss cut whose 5 minutes are up and whose clock tries are not used up.
    Anything odd or missing in the wait record means no clock retry (fail closed)."""
    try:
        if not (w.get("cutting") and kind == "cut loss" and w.get("first")):
            return ""
        if w.get("clock_n", 0) >= LOSSCUT_CLOCK_MAX:
            return "cap"
        return "due" if time.time() - float(w["clock_at"]) >= LOSSCUT_CLOCK_SECS else ""
    except Exception:
        return ""


def combo_wait_why(t, h, f, line, kind=""):
    """'' to go ahead, else why this combo still waits after buyers backed out (logged once a wait). Something must
    have changed since the failed round: the games (combo_game_snap), the combo's chance, the cached offer, the line."""
    w = COMBO_WAIT.get(t)
    if not w:
        return ""
    if w["key"] != ("combo", round(f, 3)):           # a different sale (the share changed): counted afresh
        COMBO_WAIT.pop(t, None)
        return ""
    if time.time() - w["at"] < COMBO_RETRY_GAP:
        return "courtesy gap"
    o = MINE["cash"].get(t) or {}
    seen = o.get("offer") if o.get("rfq") not in (None, "estimate") and o.get("at", 0) > w["at"] else None
    snap = combo_game_snap(h)
    why = ("the game changed" if _game_changed(snap, w["snap"]) else
           "the combo's chance moved" if _moved(h.get("p"), w["p"], COMBO_RETRY_MIN_P) else
           "the offer moved" if seen and _moved(seen, w["offer"], COMBO_RETRY_MIN_USD) else
           "the smart-sell line moved" if _moved(line, w["line"], COMBO_RETRY_MIN_USD) else "")
    clock = _clock_due(w, kind) if not why else ""
    if clock == "due":                               # #396: nothing moved, but a stuck loss cut gets its 5-minute try
        w["clock_n"] = w.get("clock_n", 0) + 1
        why = f"loss-cut clock retry {w['clock_n']} of {LOSSCUT_CLOCK_MAX} (every {LOSSCUT_CLOCK_SECS // 60} min)"
    if clock == "cap" and not w.get("cap_told"):
        w["cap_told"] = True
        log_decision({"combo": h.get("label", t), "ticker": t, "kind": "combo", "result": "skipped", "round": w["total"],
                      "why": f"loss-cut clock retries used up ({LOSSCUT_CLOCK_MAX}); waiting for the game or price to change"})
    if why:                                          # go (logged with the next round); the new state is the baseline,
        w.update(why_now=why, at=time.time(), snap=snap, p=h.get("p") or 0.0, line=line, told=False,
                 clock_now=bool(clock == "due"), clock_at=time.time())
        if seen:                                     # so a pass that then skips for another reason waits again
            w["offer"] = seen
        return ""
    if not w.get("told"):
        w["told"] = True
        log_decision({"combo": h.get("label", t), "ticker": t, "kind": "combo", "result": "skipped",
                      "why": "waiting for the game or the price to change", "round": w["total"]})
    return "waiting for the game or the price to change"


def _low_words(info):
    """Why a fresh offer was turned down, in the words Pete knows: what he paid, or the smart-sell price."""
    low, floor, line = info.get("low_offer") or 0, info.get("floor"), info.get("line")
    if floor is not None and low < floor:
        return f"under the {money(floor)} you paid"
    if line is not None:
        return f"under the {money(line)} smart sell needs"
    return "too far under the first offer"


def combo_fail_note(label, info, stop, wait, msg):
    """The plain push for an automatic combo sale that didn't go through: no 'took the profit' words (#334 for combos)."""
    n = (info or {}).get("rounds") or 0
    tries = f"{n} time{'s' if n != 1 else ''}"
    said = {"cancelled": f"the buyer backed out {tries}",
            "failed": f"the buyer backed out {tries}",
            "out of time": f"the buyer backed out {tries} and it ran out of time for this check",
            "no fresh offer": f"the buyer backed out {tries} and no fresh offer came in",
            "offer too low": f"the buyer backed out {tries} and the next offer "
                             f"({money((info or {}).get('low_offer') or 0)}) was {_low_words(info or {})}"}.get(stop)
    head = f"🤖 Auto cash-out tried to sell {label}: {said}, so nothing was sold." if said else \
        f"🤖 Auto cash-out didn't sell {label} this time (Kalshi didn't take the sale), so nothing was sold."   # no raw error text (#384)
    return head + (" Still holding, and we'll keep watching: it will try again when the game or the price changes." if wait
                   else " Still holding, and we'll keep watching: it will try again on the next check.")


def notify(msg):
    try:
        import notification
        notification.schedule(msg, delay=0, sound_name="default")
    except Exception:
        console_note(msg)


def diff_alerts(old, new):
    """Plain-English alerts for picks and combos that were decided since the last check."""
    alerts, leg_news = [], {}
    for t, c in new.items():
        o = old.get(t)
        if not o:
            continue
        if c["status"] != o["status"] and c["status"] in ("won", "lost"):
            if c["status"] == "won":
                alerts.append(f"🎉 {c['label']} hit! Pays {money(c['pays'])}.")
            else:
                why = next((n for lt, (n, r) in c["legs"].items() if r == "no" and o["legs"].get(lt, (n, None))[1] != "no"), None)
                alerts.append(f"❌ {c['label']} is out" + (f": {why} lost." if why else "."))
        elif c["status"] == "pending":
            for lt, (name, r) in c["legs"].items():
                if r == "yes" and o["legs"].get(lt, (name, None))[1] != "yes":
                    left = sum(1 for _, (_, rr) in c["legs"].items() if not rr)
                    leg_news.setdefault(name, []).append((c["label"], left))
    for name, combos in leg_news.items():
        alive = ", ".join(f"{lab} ({left} left)" for lab, left in combos[:3])
        alerts.append(f"✅ {name} won. Still alive: {alive}.")
    return alerts


# ================================================================ cash out
OFFER_LIFE = 150      # minimum seconds a cash-out offer is kept (see offer_life)


def offer_life():
    """Keep each offer until the next fresh one is due, so there's always one to confirm."""
    return max(OFFER_LIFE, int(CFG.get("cash_every", 2) * 60) + 45)


def single_value(p, pays, W):
    """What a p chance of `pays` is worth to you as a sure amount, given money W
    (your bankroll plus what's locked in). Bigger amounts get discounted more."""
    if pays <= 0 or p <= 0:
        return 0.0
    return math.exp(p * math.log(W + pays) + (1 - p) * math.log(W)) - W


def fresh_offer(t):
    import time
    o = MINE["cash"].get(t)
    if o and o.get("offer") and o.get("rfq") and time.time() - o["at"] <= offer_life() and t in MINE["hold"]:
        return o
    return None


def weekend_stats(acts):
    """Average, guaranteed part and chance of nothing more, for a hold/cash choice per combo."""
    live, pats = MINE["hold"], MINE.get("patterns") or {}
    W = max(CFG["bankroll"], 1) + MINE.get("locked", 0)
    sure = sum(f * live[t]["pays"] * acts_price(t) for t, f in acts.items() if f)
    n = sum(pats.values()) or 1
    eu = mean = zero = 0.0
    for pat, c in pats.items():
        x = sure + sum((1 - acts.get(t, 0)) * live[t]["pays"] for t in pat if t in live)
        eu += c * math.log(W + x)
        mean += c * x
        zero += c if x - sure < 0.005 else 0
    return {"eu": eu / n, "mean": mean / n, "sure": sure, "nothing": zero / n,
            "worth": math.exp(eu / n) - W}


def acts_price(t):
    o = fresh_offer(t)
    return o["offer"] / o["contracts"] if o and o["contracts"] else 0.0


def day_money(mine):
    """What actually finished today: money back from combos that won or were cashed today, what they cost,
    and the profit. "Today" is when the combo finished (the Mac's record of it, else its last game's date),
    not when it was bought, so a combo cashed yesterday with games tomorrow doesn't count today."""
    today = dt.datetime.now(PACIFIC).date()
    when = {}
    if STORE.get("db"):
        for r in store_rows("select combo, settled from bets where settled is not null"):
            try:
                when[r["combo"]] = dt.datetime.fromtimestamp(float(r["settled"]), PACIFIC).date()
            except (TypeError, ValueError, OSError):
                pass
    back = cost = 0.0
    won = cashed = lost = 0
    for a in mine:
        st = a["status"]
        if st not in ("won", "lost", "cashed"):
            continue
        d = when.get(a["ticker"])
        if d is None:
            try:
                d = dt.date.fromisoformat(a.get("week") or "")
            except ValueError:
                continue
            if st == "cashed" and d > today:
                continue                       # sold early, day unknown: don't guess it was today
        if d != today:
            continue
        got = a["back"] if st == "cashed" else a["pays"] if st == "won" else 0.0
        back += got
        cost += a["cost"]
        won += st == "won"
        cashed += st == "cashed"
        lost += st == "lost"
    return {"back": round(back, 2), "cost": round(cost, 2), "pl": round(back - cost, 2),
            "won": won, "cashed": cashed, "lost": lost}


# ---- bets you placed on Kalshi yourself vs. ones the app bought ----
APP_SEEN = {"at": 0, "set": set()}
HELD_FILE = os.path.join(HERE, "held_events.json")


def _app_table():
    store_x("create table if not exists app_bets(ticker text primary key, ts real, how text)")


def mark_app(ticker, how="app"):
    """Remember that the app (panel, Build, standing orders, killer deals, hedges) bought this market."""
    if not (STORE["db"] and ticker):
        return
    try:
        _app_table()
        store_x("insert or ignore into app_bets values(?,?,?)", (ticker, time.time(), how))
        APP_SEEN["at"] = 0
    except Exception as err:
        print("mark_app:", type(err).__name__, err)


def note_app_order(method, path, body):
    """Called for every signed Kalshi request: buys (and combo price requests) are the app's."""
    if method != "POST" or not isinstance(body, dict):
        return
    if path == "/portfolio/orders" and body.get("action", "buy") == "buy":
        mark_app(body.get("ticker"), "order")
    elif path == "/portfolio/events/orders" and (body.get("side", "bid") == "bid" or not body.get("reduce_only")):
        mark_app(body.get("ticker"), "order")      # V2: bid = buy YES; an ask that isn't sell-only buys NO
    elif path == "/communications/rfqs":
        mark_app(body.get("market_ticker"), "combo")


def app_bets():
    """Markets the app bought (None where there's no history store, e.g. the phone)."""
    if not STORE["db"]:
        return None
    if time.time() - APP_SEEN["at"] > 20:
        try:
            _app_table()
            APP_SEEN.update(at=time.time(), set={r["ticker"] for r in store_rows("select ticker from app_bets")})
        except Exception:
            return None
    return APP_SEEN["set"]


def seed_origins(held):
    """The first time: everything already held was bought before this tracking existed, so it counts as the app's."""
    got = app_bets()
    if got is None or "__seeded__" in got:
        return
    for t in list(held) + ["__seeded__"]:
        mark_app(t, "before")


def is_own(t):
    """True for a bet you placed on Kalshi yourself (not through the app)."""
    got = app_bets()
    return bool(got) and "__seeded__" in got and bool(t) and t not in got


SELF_SELL = os.path.join(HERE, "combo_selfsell.json")


def self_sell_set():
    """Bets you've switched to "I'll sell it" on Live: smart sell leaves those alone."""
    return set(load_json(SELF_SELL, {}))


def set_self_sell(t, mine):
    """mine=True: you'll sell this one yourself. False: smart sell watches it (the default for every bet)."""
    d = load_json(SELF_SELL, {})
    if mine:
        d[t] = time.time()
    else:
        d.pop(t, None)
    save_json(SELF_SELL, d)


# (#400) Pete's own sale tap and an automatic sale round can run in different processes (the web app and the watcher).
# While a tap is selling a bet, a small marker file says so (written by the web app, read by the automatic paths); the
# automatic sellers skip that bet and try again next round. One direction only: Pete's tap never reads it, so it can
# never be held up, delayed or refused by the automatic side (a lock both sides waited on could stall a sale).
MANUAL_SELL = os.path.join(HERE, "combo_manual_sell.json")
MANUAL_SELL_MAX = 90     # seconds: a marker older than this is a crashed tap's leftover and counts for nothing
_MS_LOCK = threading.Lock()


class manual_sell_mark:
    """`with manual_sell_mark(t):` around Pete's own sale tap on bet t. Never raises and never waits: if the marker
    can't be written the tap goes ahead without it."""

    def __init__(self, t):
        self.t = str(t or "")

    def __enter__(self):
        try:
            with _MS_LOCK:
                d = {}
                for k, v in load_json(MANUAL_SELL, {}).items():
                    try:                                  # one bad entry is dropped; it never stops our own marker
                        if 0 <= time.time() - float(v) < MANUAL_SELL_MAX:
                            d[k] = v
                    except Exception:
                        pass
                d[self.t] = time.time()
                save_json(MANUAL_SELL, d)
        except Exception:
            pass
        return self

    def __exit__(self, *exc):
        try:
            with _MS_LOCK:
                d = load_json(MANUAL_SELL, {})
                if d.pop(self.t, None) is not None:
                    save_json(MANUAL_SELL, d)
        except Exception:
            pass
        return False


def manual_selling(t):
    """True while Pete's own tap is selling bet t (a fresh marker): the automatic sellers leave it alone this round."""
    try:
        return 0 <= time.time() - float(load_json(MANUAL_SELL, {}).get(str(t)) or 0) < MANUAL_SELL_MAX   # future-dated = stale
    except Exception:
        return False


def hands_off(t):
    """Smart sell (and hedging and take-profit orders) skip a bet you've set to "I'll sell it"."""
    return bool(t) and t in self_sell_set()


def single_sell_reason(x, bid, ask, track=True, cut_ok=False, more=None, cap=None):
    """Smart sell for a single bet, spread or total: the same rules as combos, on Kalshi's order book. A learned
    "cut loss" also needs `cut_ok` (cut_loss_single_check: every loss guard held); without it, never.
    `more` ("A" or "B") is smart sell more's second look (more_eval): "A" the lower profit floor for a cheap single
    (MORE_FLOOR, never above the league's own), "B" the seeded loss cut-off (MORE_LOSS, only where the league has
    none yet); each answers only with its own kind of sale. Without it, exactly as before.
    `cap` (#375, PAPER ONLY, never passed by a live seller): the most smart sell's profit floor may ask for the whole
    position; None = today's rule, untouched. Only exit_cap_shadow passes it, to record what the capped rule would do.
    Returns (reason, the least it may sell the whole position for, after fees) or (None, floor shown on Live)."""
    n, cost, q = x.get("n") or 0, x.get("cost") or 0, x.get("chance")
    if not n or bid is None or bid <= 0 or q is None or x.get("state") not in ("live", "pre"):
        return None, 0.0
    net = n * (bid - single_fee(bid))
    t = x["t"]
    peak = MINE.setdefault("peak", {})
    if track:
        peak[t] = max(peak.get(t, 0.0), net)
    prm = {"tp": float(CFG.get("take_profit") or 0) / 100, "trail": CFG.get("lock_trail", True), "cut_ok": cut_ok,
           **knob_exit_prm([t])}                      # self-tuning's numbers (#228 PR3): {} while it is off
    pr = smart_params([t])
    rl = ride_lam()
    if CFG.get("smart_sell", True) and rl is not None:
        leg = _score_leg(t, x.get("kind") or "win", x.get("side") or "yes", x.get("sport") or "")
        lam, _ = swing_lambda({"need": [((leg["side"], leg["ticker"]), "")], "legs_left": [(q, x.get("state") == "live", 0)]})
        lam *= pr["lam"] * rl
        flr, loss = pr["floor"], pr["loss"]
        if more == "A":
            flr, loss = min(flr, MORE_FLOOR), None
            prm["cut_ok"] = False
        elif more == "B" and loss is None:
            loss = MORE_LOSS
        prm.update(smart=True, lam=lam, floor=flr, loss=loss)
        if cap is not None and cost > 0:
            prm["floor"] = min(prm["floor"], cap / cost)     # paper rule only: floor x cost never above what it can sell for
    d = exit_policy({"kind": "single", "value": net, "peak": peak.get(t, 0.0), "pays": n, "cost": cost, "q": q,
                     "live": x.get("state") == "live"}, prm)
    if more and d["reason"] != {"A": "smart", "B": "cut loss"}[more]:
        return None, d["floor"]
    return (d["reason"], d["threshold"]) if d["sell"] else (None, d["floor"])


SELL_TOP = 0.99   # Kalshi's highest price for one contract: no bid or cash-out offer pays more (issue #371)


def sell_top(pays, single=False):
    """The most a held bet can ever sell for, whole (issue #371): a combo's payout at 99¢ a contract; a single's
    contracts at the 99¢ top bid less Kalshi's fee per contract, as single_sell_reason values it."""
    pays = float(pays or 0)
    return pays * (SELL_TOP - single_fee(SELL_TOP)) if single else pays * SELL_TOP


def sell_line_shown(line, top):
    """A sell line for the screen (issue #371): (line, False) when a sale could reach it, (None, True) when it is above
    `top` (the most the bet can sell for), so no screen ever says "sells at $14+" on a bet that pays $13. Display only:
    every sell decision still compares the offer with the unclamped line, so nothing sells that didn't before."""
    if not line:
        return None, False
    if line > top + 0.005:
        return None, True
    return round(line, 2), False


# ---- #375 paper test: smart sell's profit line for a favorite bought above ~1/floor is above what the bet can ever sell
# for, so it can never take a profit (it holds to settlement). This RECORDS what a line capped at the top price less a
# margin would have done, beside what today's rule does. Write-only: nothing reads the table back into a decision, no
# order is placed, `single_sell_reason` is called with track=False (no peak is touched) and every failure is swallowed.
# Default OFF ("exit_cap_shadow"). Turning it on later is a separate decision for Pete, with this record to judge it by.
EXIT_CAP_MARGIN = 0.03        # per contract, dollars: the paper line sits this far under the top sale price
EXIT_CAP_EVERY = 300          # seconds: an unchanged answer for a bet is written at most this often
EXIT_CAP_KEEP = 60 * 86400    # rows older than this are pruned; at most EXIT_CAP_ROWS are kept
EXIT_CAP_ROWS = 100000
EXIT_CAP_SEEN = {}            # ticker -> (when written, live answer, paper answer)
EXIT_CAP_PRUNE = {"at": 0.0}


def exit_cap_shadow(x, bid, now=None):
    """Records, for a held single whose profit line is above what it can sell for, what today's rule and the capped
    paper rule each say right now: the decision ('hold' or the reason), the sale price after fees, the time. Returns
    True when a row was written. Never raises, never sells, never changes what smart sell decides."""
    try:
        if CFG.get("exit_cap_shadow") is not True or not STORE.get("db") or not x or not bid:
            return False
        now = now or time.time()
        n, cost, q = x.get("n") or 0, x.get("cost") or 0, x.get("chance")
        if not n or cost <= 0 or q is None or q < EXIT_Q_MIN:
            return False
        top = sell_top(n, single=True)
        live_why, live_line = single_sell_reason(x, bid, None, track=False)
        if not sell_line_shown(live_line, top)[1]:
            return False                                      # the line is reachable: nothing to compare
        cap = top - EXIT_CAP_MARGIN * n
        alt_why, alt_line = single_sell_reason(x, bid, None, track=False, cap=cap)
        live_d, alt_d = live_why or "hold", alt_why or "hold"
        t = x["t"]
        last = EXIT_CAP_SEEN.get(t)
        if last and last[1:] == (live_d, alt_d) and now - last[0] < EXIT_CAP_EVERY:
            return False
        EXIT_CAP_SEEN[t] = (now, live_d, alt_d)
        if len(EXIT_CAP_SEEN) > 5000:
            for k in [k for k, v in EXIT_CAP_SEEN.items() if now - v[0] > 3600]:
                EXIT_CAP_SEEN.pop(k, None)
        store_x("create table if not exists exit_cap_shadow(ts real, ticker text, kind text, side text, n real, cost real, "
                "chance real, state text, bid real, net real, top real, live_line real, live_decision text, cap real, "
                "alt_line real, alt_decision text)")
        store_x("create index if not exists exit_cap_shadow_ts on exit_cap_shadow(ts)")
        store_x("insert into exit_cap_shadow values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (round(now, 1), t, x.get("kind"), x.get("side"), n, cost, q, x.get("state"), bid,
                 round(n * (bid - single_fee(bid, n)), 4), round(top, 4), round(live_line or 0, 4), live_d,
                 round(cap, 4), round(alt_line or 0, 4), alt_d))
        if now - EXIT_CAP_PRUNE["at"] > 6 * 3600:
            EXIT_CAP_PRUNE["at"] = now
            store_x("delete from exit_cap_shadow where ts < ?", (now - EXIT_CAP_KEEP,))
            store_x("delete from exit_cap_shadow where rowid in (select rowid from exit_cap_shadow order by ts "
                    "limit max((select count(*) from exit_cap_shadow) - ?, 0))", (EXIT_CAP_ROWS,))
        return True
    except Exception as err:
        try:
            console_note(f"exit cap shadow: {type(err).__name__}: {err}")
        except Exception:
            pass
        return False


SINGLE_RESTING = {"at": 0, "t": set()}


def resting_single_sells():
    """Singles with a sell order already waiting on Kalshi (a sell-early favorite's exit, or one you placed)."""
    if time.time() - SINGLE_RESTING["at"] > 60:
        try:
            data = kalshi_send("GET", "/portfolio/orders", params={"status": "resting", "limit": 200}) or {}
            SINGLE_RESTING.update(at=time.time(), t={o.get("ticker") for o in data.get("orders", [])
                                                      if order_may_sell(o, None) and not is_combo(o.get("ticker"))})
        except Exception:
            return None
    return SINGLE_RESTING["t"]


def order_may_sell(o, held="yes"):
    """Whether a resting order (or a fill) sells `held` contracts. Uses Kalshi's legacy action/side when it still
    sends them; without them, the newer outcome/book side (selling YES = long NO = book side "ask"). For a single,
    whose held side the order list doesn't say, an order without the legacy fields counts (smart sell then stays out
    of its way rather than selling twice)."""
    if o.get("action") in ("buy", "sell"):
        return o["action"] == "sell"
    out = o.get("outcome_side") or {"bid": "yes", "ask": "no"}.get(o.get("book_side"))
    if held is None:
        return True
    return out is not None and out != held


@in_scope("sell")
def sell_single_now(t, side, n, price, coid=None):
    """Sell n contracts of a single bet at `price` or better, now or not at all. Returns (sold, error)."""
    import uuid
    body = {"ticker": t, "action": "sell", "side": side, "type": "limit", "count": int(n),
            f"{side}_price": max(1, int(math.floor(price * 100 + 1e-6))), "time_in_force": "immediate_or_cancel",
            "reduce_only": True, "client_order_id": coid or str(uuid.uuid4())}
    if body["count"] < 1:
        return 0, "under one contract"
    try:
        o = (kalshi_send("POST", "/portfolio/orders", body) or {}).get("order") or {}
    except PermissionError as err:                 # Kalshi's own reason (#134), never a guess about the key
        return 0, str(err)
    except Exception as err:                       # unknown outcome: "check", never sold again (no sale on top)
        if order_outcome(err) == "unknown":
            SINGLES["at"] = 0
            return 0, f"check: {order_words(err)}"
        return 0, f"Kalshi didn't take the order: {order_words(err)}"
    filled = float(o.get("fill_count_fp") or o.get("fill_count") or
                   (body["count"] - float(o.get("remaining_count") or 0) if o.get("status") == "executed" else 0))
    ACCT_CACHE["at"] = 0
    SINGLES["at"] = 0
    ACCT_POS["at"] = 0
    return filled, None


SINGLES_SELL_AGE = 180      # seconds: smart sell for singles never acts on prices older than this
SELL_MIN_CONTRACTS = 1      # Kalshi's smallest order: a leftover under one contract is never offered (#334)
SELL_FAIL_MAX = 3           # failed identical sales (same market, side and size) in a row before smart sell waits
SELL_FAIL_WAITS = (600, 3600)   # then 10 minutes; any failure after that wait: an hour each time
SELL_FAILS = {}             # ticker -> {"key", "n", "level", "until"} (this process only; a restart starts over)


def sell_backoff_left(t, side, count, now=None):
    """Seconds smart sell still waits before trying this sale again, or 0. Only ever makes it try less (#334)."""
    s = SELL_FAILS.get(t)
    if not s:
        return 0
    if s["key"] != (side, count):                  # a different sale (the size changed): counted afresh
        SELL_FAILS.pop(t, None)
        return 0
    return max(0.0, s.get("until", 0) - (now or time.time()))


def sell_backoff_note(t, side, count, rec, err, now=None):
    """One more failed sale of `count` contracts of t. After SELL_FAIL_MAX in a row it waits 10 minutes, then an
    hour after every further failure; the wait is logged once each time it starts."""
    now = now or time.time()
    s = SELL_FAILS.get(t)
    if not s or s["key"] != (side, count):
        s = SELL_FAILS[t] = {"key": (side, count), "n": 0, "level": 0, "until": 0}
    s["n"] += 1
    if s["n"] < SELL_FAIL_MAX and not s["level"]:
        return 0
    wait = SELL_FAIL_WAITS[min(s["level"], len(SELL_FAIL_WAITS) - 1)]
    s.update(n=0, level=s["level"] + 1, until=now + wait)
    words = f"failed {SELL_FAIL_MAX} times in a row" if s["level"] == 1 else "failed again"
    log_decision(dict(rec, result="skipped", why=f"waiting {wait // 60} min: the sale {words}",
                      note=str(err or "")[:140]))
    console_note(f"smart sell: {t} {words} ({str(err or '')[:80]}); waiting {wait // 60} min before trying again")
    return wait


# ---------------------------------------------------------------- smart sell more (Pete's opt-in, 2026-11-24)
# Two extra ways smart sell may sell a SINGLE, each behind its own Settings switch (on by default: Pete opted in; both
# can be turned off), both inside one daily dollar cap, both only on FRESH, LIVE numbers, never on a stale reference.
#   A  a lower profit floor on cheaper singles: bought under MORE_UNDER (60c) a contract, it may sell at MORE_FLOOR
#      (1.35x what you paid, the conservative end of 1.3-1.35x; never above the league's own learned floor, never
#      under smart sell's own lower bound of 1.2x) when the usual risk-adjusted hold-value comparison, the 50% chance
#      minimum and every sell guard still say sell.
#   B  the learned loss cut, earlier, on a single in play that is clearly sliding: where the league has no cut of its
#      own yet (it needs 30 settled bets), the tuner's own first number, MORE_LOSS (15%), stands in, with ALL the loss
#      guards: a fresh score, a game at least half played, 3+ confirming checks over 3+ minutes, never at a break, a
#      real fall from the pregame chance, never in 'Never sell at a loss' mode.
# What counts as fresh (fails closed: no new-path sale on anything older, missing or one-sided): the price must come
# from a Kalshi fetch made within MORE_AGE seconds (SINGLES["mk_at"], per market: a fetch that failed and fell back to
# the old copy never stamps it), with a bid AND an ask within LIVE_SPREAD, the chance is taken from that live
# middle (never last trade, never a pregame number, never a sportsbook line), and the game's score feed must be fresh
# (SL_FEED_AGE) and the game under way. The pregame chance is used only by the loss guard that was already there.
# more_eval works out both verdicts once per pass: smart_sell_singles acts on them only when the switch is on,
# more_shadow records them (write-only) to measure net dollars after fees against holding.
MORE_FLOOR = 1.35          # A: profit floor, x cost
MORE_UNDER = 0.60          # A: only singles bought under this price per contract
MORE_LOSS = 0.15           # B: the cut-off stand-in (the self-tuning registry's first value for the loss cut)
MORE_AGE = 120             # seconds: the quote must come from a Kalshi fetch no older than this
MORE_PROG_MIN = 0.50       # B: never earlier in the game than this share played, whatever the tuner learned
MORE_CHECKS_MIN = 3        # B: never fewer confirming checks than this, whatever the tuner learned
MORE_CAP_MAX = 200.0        # the Settings slider's top: a saved number above it (the watcher accepts any float) reads as this
MORE_CAP_DEFAULT = 50.0    # the STARTING dollars a day through A and B together (gross sale value); unreadable = this
MORE_SW = {"at": 0.0, "v": None}


def more_settings():
    """{'a': bool, 'b': bool, 'cap': dollars}: the two switches and the daily cap, read from the shared settings file
    too (like knob_switch_on), at most every 10 seconds. A missing file = the defaults; a damaged file or any error
    = both OFF; an unreadable cap = MORE_CAP_DEFAULT, never unlimited."""
    t = time.monotonic()
    if MORE_SW["v"] is None or t - MORE_SW["at"] > 10:
        try:
            if os.path.exists(MAIN_SAVED):
                with open(MAIN_SAVED) as f:
                    d = json.load(f)
                if not isinstance(d, dict):
                    raise ValueError("settings file is not a dict")
            else:
                d = {}
            raw = CFG.get("sell_more_cap", MORE_CAP_DEFAULT) if d.get("sell_more_cap") is None else d["sell_more_cap"]
            try:
                cap = float(raw)
                if not math.isfinite(cap) or cap < 0:
                    cap = MORE_CAP_DEFAULT
                cap = min(cap, MORE_CAP_MAX)
            except (TypeError, ValueError):
                cap = MORE_CAP_DEFAULT
            v = {"a": shared_flag("sell_more_cheap"), "b": shared_flag("sell_more_loss"), "cap": cap}
        except Exception:
            v = {"a": False, "b": False, "cap": MORE_CAP_DEFAULT}
        MORE_SW.update(at=t, v=v)
    return dict(MORE_SW["v"])


def more_sold_today():
    """Dollars (the sale's offer) today's smart sell more sales and unclear ones ("check" may have gone through) came to,
    from the decision log's tagged lines. A missing log is 0; a log that can't be read, or a tagged line that can't be
    parsed, returns None (the caller treats it as the cap reached: fail closed)."""
    today = dt.date.today().isoformat()
    total = 0.0
    try:
        with open(SELL_LOG, encoding="utf-8") as f:
            for line in f:
                if '"more": ' not in line or f'"when": "{today}' not in line:
                    continue
                r = json.loads(line)
                if r.get("more") and r.get("result") in ("sold", "check"):
                    total += float(r.get("offer") or 0)
    except FileNotFoundError:
        return 0.0
    except (OSError, ValueError, TypeError):
        return None
    return total


def more_braked(tickers):
    """Self-tuning's brake holds this league (so no stand-in cut-off may turn the loss cut back on); unreadable = braked."""
    if not knob_switch_on():
        return False
    try:
        _, chain = _knob_bet_chain(tickers)
        st, now = knob_state_cached(), time.time()
        return any(_knob_braked(st, g, now) for g in chain)
    except Exception:
        return True


def more_fresh(x, m, now):
    """The live reference smart sell more may act on: ((bid, ask, chance), '') or (None, why not). The market's own
    fetch must be young (MORE_AGE), its book two-sided within LIVE_SPREAD, and its game in play on a fresh score
    feed; the chance is that book's middle, recomputed here."""
    at = (SINGLES.get("mk_at") or {}).get(x["t"])
    if not at or now - at > MORE_AGE or now < at - 5:
        return None, "price not fresh"
    side = x["side"]
    bid, ask = dollars(m, f"{side}_bid"), dollars(m, f"{side}_ask")
    if not bid or not ask or bid <= 0 or ask <= 0 or ask < bid or round(ask - bid, 4) > LIVE_SPREAD:
        return None, "no live two-sided price"
    if x.get("state") != "live":
        return None, "game not in play"
    leg = _score_leg(x["t"], x.get("kind") or "win", side, x.get("sport") or "")
    sc, why = fresh_live_score(leg["ticker"], leg["side"], now)
    if not sc:
        return None, why
    return (bid, ask, round((bid + ask) / 2, 4)), ""


def more_eval(x, m, now=None):
    """What A and B would each do for this single right now, whatever their switches say: {'a': {...}, 'b': {...},
    'bid', 'ask', 'q', 'age'}; each verdict has 'would' (bool), 'why' (the sale's reason, or why not) and 'floor'. Works
    only from more_fresh's live numbers. B's confirming checks count under their own key ("cutB:"), never the real
    loss cut's. Pure of orders and of Kalshi calls."""
    now = now or time.time()
    t = x["t"]
    at = (SINGLES.get("mk_at") or {}).get(t)
    res = {"a": {"would": False, "why": "", "floor": 0.0}, "b": {"would": False, "why": "", "floor": 0.0},
           "bid": None, "ask": None, "q": None, "age": round(now - at, 1) if at else None}
    fresh, why = more_fresh(x, m, now)
    if not fresh:
        res["a"]["why"] = res["b"]["why"] = why
        return res
    bid, ask, q = fresh
    res.update(bid=bid, ask=ask, q=q)
    x2 = dict(x, chance=q)
    pr = smart_params([t])
    n, cost = x.get("n") or 0, x.get("cost") or 0
    a, b = res["a"], res["b"]
    if not n or not cost:
        a["why"] = "no cost known"
    elif cost / n >= MORE_UNDER:
        a["why"] = "not a cheap bet"
    elif pr["floor"] <= MORE_FLOOR:
        a["why"] = "league floor already lower"
    else:
        why, fl = single_sell_reason(x2, bid, ask, track=False, more="A")
        a.update(would=bool(why), why=why or "under the lower floor", floor=fl)
    if not CFG.get("smart_sell", True) or ride_lam() is None:
        b["why"] = "loss cuts are off"
    elif pr["loss"] is not None:
        b["why"] = "league has its own cut-off"
    elif more_braked([t]):
        b["why"] = "self-tuning brake"
    else:
        leg = _score_leg(t, x.get("kind") or "win", x.get("side") or "yes", x.get("sport") or "")
        sp = stoploss_params([t])
        sp = dict(sp, prog=max(sp["prog"], MORE_PROG_MIN))
        ok, gw = stop_loss_leg(leg["ticker"], leg["side"], single_pre(x), q, sp, now)
        if ok and not q <= MORE_LOSS:
            ok, gw = False, "not under the cut-off"
        checks, span, gap = sl_confirm_params([t])
        ready, gw = _sl_confirm("cutB:" + t, ok, gw, now, (max(checks, MORE_CHECKS_MIN), max(span, SL_SPAN), min(gap, SL_GAP)))
        why, fl = single_sell_reason(x2, bid, ask, track=False, cut_ok=ready, more="B")
        b.update(would=bool(why), why=why or gw or "held", floor=fl)
    return res


# The daily limit is not fixed: it STARTS at the Settings number (MORE_CAP_DEFAULT, $50) and moves by one plain rule
# (Pete, 2026-11-24), worked out from the record alone (no network): each of these sales, once its game is over, is
# compared with what holding would have paid (the sale log's outcome, the same follow-up the scorecard uses), net of the
# sale's fee. `gain` = what the sale brought after fees minus what holding paid.
#   - Nothing moves until MORE_MIN_N (20) of them have finished games.
#   - Then, after every MORE_BLOCK (10) more, look at the last MORE_WINDOW (20): if selling beat holding by more than
#     MORE_EDGE ($1) after fees, the limit grows by 25% (never more than once a week, never over MORE_MAX_MULT x the
#     start); if it did worse than holding, the limit is cut in half (never under MORE_MIN_MULT x the start).
#   - The brake: MORE_STREAK (4) sales in a row that did worse than holding, or the last 30 days under holding by
#     MORE_DRAW ($25), pauses both ways for MORE_PAUSE_DAYS (7); then they start again at the smallest limit and must
#     earn the way back up (nothing carries over).
# Deterministic: the same record always gives the same limit. Stored: combo_more.json (what the Settings page shows
# and what the engine falls back on if the record can't be read); never read from the shadow table.
MORE_MIN_N, MORE_BLOCK, MORE_WINDOW = 20, 10, 20
MORE_UP, MORE_DOWN, MORE_MAX_MULT, MORE_MIN_MULT, MORE_UP_DAYS = 1.25, 0.5, 4.0, 0.2, 7
MORE_EDGE, MORE_STREAK, MORE_DRAW, MORE_PAUSE_DAYS, MORE_LOSE = 1.0, 4, 25.0, 7, 0.01
MORE_FILE = os.path.join(HERE, "combo_more.json")
MORE_LIM = {"at": 0.0, "v": None}


def more_settled(now):
    """This device's smart-sell-more sales whose games are over: [{'ts': when the result was known, 'gain', 'net', 'held'}],
    oldest first. Raises on anything unreadable (the caller then uses the stored state and the smallest limit)."""
    out = []
    try:
        with open(SELL_LOG, encoding="utf-8") as f:
            lines = [ln for ln in f if '"more": ' in ln and '"result": "sold"' in ln]
    except FileNotFoundError:
        lines = []
    _ledger_table()
    for ln in lines:
        r = json.loads(ln)
        if not r.get("more") or r.get("at") is None or r.get("net") is None:
            continue
        got = store_rows_strict("select outcome, held, done from sell_log where ts=? and ticker=? and result='sold'",
                                (r["at"], r.get("ticker") or ""))
        if got and got[0]["outcome"] in ("won", "lost") and got[0]["held"] is not None and got[0]["done"]:
            out.append({"ts": float(got[0]["done"]), "net": float(r["net"]), "held": float(got[0]["held"]),
                        "gain": round(float(r["net"]) - float(got[0]["held"]), 4)})
    return sorted(out, key=lambda r: r["ts"])


def more_replay(res, now):
    """The rule above, applied oldest to newest. Returns {'mult', 'paused_until', 'n', 'gain', 'why'}; `n`/`gain` count
    the current stretch (since the last pause)."""
    mult, until, last_up, seq, streak, why = 1.0, 0.0, 0.0, [], 0, ""
    for r in res:
        ts = r["ts"]
        if until and ts < until:
            continue                                   # settled during a pause: made before it, not counted
        if until:                                      # the pause is over: start again at the smallest limit
            mult, until, seq, streak, last_up = MORE_MIN_MULT, 0.0, [], 0, ts
            why = "Restarted small after a pause; it has to earn its way back up."
        seq.append(r)
        streak = streak + 1 if r["gain"] < -MORE_LOSE else 0
        month = sum(x["gain"] for x in seq if x["ts"] > ts - 30 * 86400)
        if streak >= MORE_STREAK or month <= -MORE_DRAW:
            until = ts + MORE_PAUSE_DAYS * 86400
            why = (f"Paused: {MORE_STREAK} sales in a row did worse than holding." if streak >= MORE_STREAK else
                   f"Paused: the last 30 days did ${-month:.0f} worse than holding.")
            continue
        n = len(seq)
        if n >= MORE_MIN_N and (n - MORE_MIN_N) % MORE_BLOCK == 0:
            g = sum(x["gain"] for x in seq[-MORE_WINDOW:])
            if g > MORE_EDGE and ts - last_up >= MORE_UP_DAYS * 86400 and mult < MORE_MAX_MULT:
                mult, last_up = min(MORE_MAX_MULT, mult * MORE_UP), ts
                why = f"Raised: the last {MORE_WINDOW} finished sales beat holding by ${g:.2f} after fees."
            elif g < 0 and mult > MORE_MIN_MULT:
                mult = max(MORE_MIN_MULT, mult * MORE_DOWN)
                why = f"Cut: the last {MORE_WINDOW} finished sales did ${-g:.2f} worse than holding."
    if until and now >= until:
        mult, until, seq = MORE_MIN_MULT, 0.0, []      # paused time is up and nothing new settled yet
        why = "Restarted small after a pause; it has to earn its way back up."
    return {"mult": mult, "paused_until": until, "n": len(seq), "gain": round(sum(x["gain"] for x in seq), 2), "why": why}


def more_limit(now=None, fresh=False):
    """Today's limit on dollars sold by smart sell more: {'limit', 'start', 'mult', 'paused', 'paused_until', 'n', 'gain',
    'why'}. `limit` is 0 while paused. Cached a minute. Any problem reading the record uses the stored state, else the
    SMALLEST limit (never the start): the limit can only be bigger than the start from a record that was read."""
    now = now or time.time()
    if not fresh and MORE_LIM["v"] is not None and now - MORE_LIM["at"] < 60:
        return dict(MORE_LIM["v"])
    start = more_settings()["cap"]
    try:
        if not STORE.get("db"):
            raise RuntimeError("history file not open")
        r = more_replay(more_settled(now), now)
        save_json(MORE_FILE, dict(r, at=int(now)))
    except Exception as err:
        console_note(f"smart sell more limit: {type(err).__name__}: {err}")
        d = load_json(MORE_FILE, {})
        try:
            r = {"mult": float(d["mult"]), "paused_until": float(d.get("paused_until") or 0), "n": int(d.get("n") or 0),
                 "gain": float(d.get("gain") or 0), "why": str(d.get("why") or "")}
            if not math.isfinite(r["mult"]) or not math.isfinite(r["paused_until"]):
                raise ValueError("non-finite saved state")   # NaN would make every comparison false: never a limit
            if r["paused_until"] and now >= r["paused_until"]:
                r["mult"], r["paused_until"] = MORE_MIN_MULT, 0.0
        except (KeyError, TypeError, ValueError):
            r = {"mult": MORE_MIN_MULT, "paused_until": 0.0, "n": 0, "gain": 0.0,
                 "why": "The record couldn't be read, so the smallest limit applies."}
    r["mult"] = min(max(float(r["mult"]), MORE_MIN_MULT), MORE_MAX_MULT)
    paused = bool(r["paused_until"] and now < r["paused_until"])
    out = dict(r, start=start, paused=paused, limit=0.0 if paused else round(start * r["mult"], 2))
    if not out["why"]:
        out["why"] = f"Starting limit. It only changes after {MORE_MIN_N} of these sales have finished games (now {out['n']})."
    MORE_LIM.update(at=now, v=out)
    return dict(out)


def more_view():
    """Settings' plain-English line: today's limit, what is used, and why."""
    try:
        v = more_limit()
        used = more_sold_today()
        return {"limit": v["limit"], "start": v["start"], "paused": v["paused"], "n": v["n"], "gain": v["gain"],
                "why": v["why"], "used": None if used is None else round(used, 2),
                "until": int(v["paused_until"]) if v["paused"] else None}
    except Exception:
        return None


def more_cap_blocks(offer):
    """Whether this sale would take today's smart-sell-more total over today's limit (more_limit). Fails closed."""
    done = more_sold_today()
    return done is None or not (done + float(offer or 0) <= more_limit()["limit"] + 1e-9)   # NaN blocks too


# smart sell more's shadow record: per pass and held single, what A and B would do (and the numbers behind it), to
# measure net dollars after fees against holding. Write-only: NOTHING in the engine reads this table (a test checks).
# Bounded, throttled, errors swallowed, off the trading path (recording happens after the verdicts are made).
MORE_SHADOW = {"every": 60, "keep_days": 60, "cap": 200000, "prune": 0.0, "made": False, "seen": {}}


def more_shadow(x, ev, sw, now=None):
    """Record one single's verdicts (about once a minute per bet). Never raises, never returns a value used by a decision."""
    try:
        if not STORE.get("db") or not CFG.get("sig_shadow", True):
            return
        now = now or time.time()
        if now - MORE_SHADOW["seen"].get(x["t"], 0) < MORE_SHADOW["every"]:
            return
        MORE_SHADOW["seen"][x["t"]] = now
        if len(MORE_SHADOW["seen"]) > 2000:
            MORE_SHADOW["seen"].clear()
        if not MORE_SHADOW["made"]:
            store_x("create table if not exists more_shadow(ts real, ticker text, label text, sport text, side text, "
                    "n real, cost real, bid real, ask real, chance real, ref_age real, a_on int, b_on int, a_would int, "
                    "a_why text, a_floor real, b_would int, b_why text, net real)")
            store_x("create index if not exists more_shadow_ts on more_shadow(ts)")
            MORE_SHADOW["made"] = True
        bid = ev.get("bid")
        net = round(float(x.get("n") or 0) * (bid - single_fee(bid)), 4) if bid else None
        a, b = ev["a"], ev["b"]
        _sig_insert({"more_shadow": [(now, x["t"], str(x.get("label") or "")[:60], x.get("sport") or "", x.get("side") or "",
                                      x.get("n"), x.get("cost"), bid, ev.get("ask"), ev.get("q"), ev.get("age"),
                                      int(bool(sw.get("a"))), int(bool(sw.get("b"))), int(a["would"]),
                                      str(a["why"])[:60], a["floor"], int(b["would"]), str(b["why"])[:60], net)]})
        if now - MORE_SHADOW["prune"] > 6 * 3600:
            MORE_SHADOW["prune"] = now
            store_x("delete from more_shadow where ts < ?", (now - MORE_SHADOW["keep_days"] * 86400,))
            n = (store_rows("select count(*) n from more_shadow") or [{"n": 0}])[0]["n"]
            if n > MORE_SHADOW["cap"]:
                store_x("delete from more_shadow where rowid in (select rowid from more_shadow order by ts limit ?)",
                        (n - MORE_SHADOW["cap"],))
    except Exception as err:
        console_note(f"smart sell more shadow: {type(err).__name__}: {err}")


def smart_sell_singles():
    """Auto cash-out for single bets, spreads and totals (yours or the app's): sells into Kalshi's order book when
    smart sell, take profit or lock-in says so. Skips ones set to "I'll sell it", ones with a sell order already
    waiting, and thin markets where the bid is far below the ask. Returns the messages to send."""
    out = []
    if time.time() - SINGLES["at"] > SINGLES_SELL_AGE:
        return out                                   # Live hasn't refreshed lately: don't act on old prices
    if sell_held(out):                               # Kalshi is refusing sales: don't ask again every pass (#134)
        return out
    resting = None
    for x in list(SINGLES["items"]):
        if hands_off(x["t"]) or x.get("state") not in ("live", "pre"):
            continue
        m = SINGLES["mk"].get(x["t"]) or {}
        side = x["side"]
        bid = dollars(m, f"{side}_bid")
        ask = dollars(m, f"{side}_ask")
        cut_ok = False                                # the learned loss cut: only once every loss guard held
        loss = smart_params([x["t"]])["loss"] if CFG.get("smart_sell", True) and ride_lam() is not None else None
        if loss:
            cut_ok, gw = cut_loss_single_check(x, loss)
            if not cut_ok and x.get("state") == "live" and x.get("chance") is not None and x["chance"] <= loss:
                note_cut_held(x["t"], x.get("label", x["t"]), "cut loss", gw)
        why, floor = single_sell_reason(x, bid, ask, cut_ok=cut_ok)
        path = None                                   # smart sell more (A / B): only where the usual rules said no
        try:
            sw = more_settings()
            ev = more_eval(x, m)                      # always worked out (and recorded), acted on only with a switch on
            more_shadow(x, ev, sw)
            if not why:
                for k, key in (("A", "a"), ("B", "b")):
                    if sw[key] and ev[key]["would"]:
                        path, why, floor = k, ev[key]["why"], ev[key]["floor"]
                        bid, ask = ev["bid"], ev["ask"]
                        break
        except Exception as err:
            console_note(f"smart sell more: {type(err).__name__}: {err}")
            path = None
        if not why:
            continue
        if ask and bid and round(ask - bid, 4) > LIVE_SPREAD:   # rounded: 56c - 50c is 6c, not 6.0000001c
            continue                                  # too thin to sell at a fair price right now
        if resting is None:
            resting = resting_single_sells()
            if resting is None:
                return out
        if x["t"] in resting or order_unsure(x["t"]):
            continue                                  # a sell waiting, or an order whose outcome is unknown
        if manual_selling(x["t"]):
            continue                                  # Pete's own Sell tap has it (#400): checked again next round
        rec = {"combo": x["label"], "ticker": x["t"], "offer": round(x["n"] * bid, 2), "cut_off": round(floor, 2),
               "why": why, "chance": x["chance"], "cost": x["cost"], "pays": x["n"], "kind": x["kind"], "side": side,
               "live": x.get("state") == "live", "ask": ask}
        if path:                                      # smart sell more: tagged for the cap and the scorecard
            rec.update(more=path, chance=ev["q"], ref_age=ev["age"],
                       net=round(x["n"] * (bid - single_fee(bid, x["n"])), 2))   # Kalshi's per-order rounded fee
        whole = int(math.floor(float(x["n"]) + 1e-6))
        if whole < SELL_MIN_CONTRACTS:                # Kalshi's minimum: a 0.92 leftover can't be sold (#334)
            log_decision(dict(rec, result="skipped", why="under one contract (Kalshi's minimum)"))
            continue
        wait = sell_backoff_left(x["t"], side, whole)
        if wait:
            continue                                  # failed again and again just now: waiting (logged once)
        if path:
            if trading_paused() or not can_trade():   # Pause read fresh right before the order, not at the pass start
                continue
            if more_cap_blocks(rec["offer"]):
                log_decision(dict(rec, result="skipped", why="daily cap reached (smart sell more)"))
                continue
        if auto_cap_reached():
            log_decision(dict(rec, result="skipped", why="daily cap reached"))
            continue
        sold, err = sell_single_now(x["t"], side, x["n"], bid)
        result = "sold" if sold else "check" if (err or "").startswith("check:") else "failed"
        log_decision(dict(rec, result=result, note=(err or f"{sold:g} sold")[:140]))
        if result == "failed":
            sell_backoff_note(x["t"], side, whole, rec, err)
        else:
            SELL_FAILS.pop(x["t"], None)
        if sold:
            MINE.get("peak", {}).pop(x["t"], None)
            got = sold * (bid - single_fee(bid))
            paid = (x.get("cost") or 0) * (sold / x["n"]) if x.get("n") else 0   # the part sold, like the sell sheet
            lead = {"take profit": "🤖 Take profit", "lock in": "🤖 Locked in a profit",
                    "smart": "🤖 Smart sell", "cut loss": "🤖 Cut a loss"}.get(why, "🤖 Smart sell") \
                + (" (smart sell more)" if path else "")
            res = sale_result_note(got, paid, cutting=(why == "cut loss"))
            out.append(f"{lead}: sold {x['label']} for about {money(got)}" + (f": {res}." if res[0] != "(" else f" {res}."))
    return out


def game_event(ev):
    return re.sub(r"(SPREAD|TOTAL)-", "GAME-", ev or "")


def note_held(events):
    events = sorted(e for e in events if e)
    old = load_json(HELD_FILE, {})
    if old.get("events") != events or time.time() - old.get("at", 0) > 300:
        save_json(HELD_FILE, {"at": time.time(), "events": events})


def account_events(max_age=1800):
    """Games you bet on Kalshi yourself (not through the app), so the panel doesn't double up on them."""
    d = load_json(HELD_FILE, {})
    return set(d.get("events") or []) if time.time() - d.get("at", 0) < max_age else set()


SINGLES = {"at": 0, "items": [], "mk": {}, "mk_at": {}}


def _bet_kind(t):
    u = (t or "").upper()
    return "spread" if "SPREAD-" in u else "total" if "TOTAL-" in u else "win" if "GAME-" in u else "other"


def _score_leg(t, kind, side, code):
    """A stand-in game pick for a single/spread/total so leg_score can find its game."""
    head, ev, tail = (t.split("-", 2) + ["", ""])[:3]
    head = re.sub(r"(SPREAD|TOTAL)$", "GAME", head)
    if kind == "spread":
        tail = re.sub(r"\d+$", "", tail)
    if kind == "total":
        teams = sport_teams(code)
        for n in (2, 3, 4):
            if ev[-n:] in teams:
                return {"ticker": f"{head}-{ev}-{ev[-n:]}", "side": "yes"}
        return {"ticker": f"{head}-{ev}-{ev[-3:]}", "side": "yes"}
    return {"ticker": f"{head}-{ev}-{tail}", "side": side}


def _line_num(text):
    m = re.search(r"(?:over|by)\s+([\d.]+)", text or "", re.I)
    return float(m.group(1)) if m else None


def _single_how(kind, side, line, sc):
    """Where a spread, total or single stands right now, in words."""
    if not sc or sc.get("me") is None or sc.get("opp") is None:
        return ""
    me, opp = float(sc["me"]), float(sc["opp"])
    if kind == "spread" and line is not None:
        margin = me - opp                       # sc is from the side this bet needs (leg_score flips for "no")
        need = line if side == "yes" else -line
        good = margin > need
        return f"{'Covering' if good else 'Not covering'} now · {'+' if margin >= 0 else ''}{margin:g}, needs {'more than ' + format(line, 'g') if side == 'yes' else 'to lose by under ' + format(line, 'g') if line else 'to win'}"
    if kind == "total" and line is not None:
        tot = me + opp
        if tot > line:                          # already over: an Over has won it, an Under has lost it
            return f"{'Over the line' if side == 'yes' else 'Not on track'} · {tot:g} so far, line {line:g}"
        played = game_played(sc)                # issue #238: mid-game an Over is always under the line, so judge the
        if played is None:                      # pace (points so far over the share of the game played), not the total
            if sc.get("state") == "post":
                return f"{'Not on track' if side == 'yes' else 'On track'} · {tot:g} final, line {line:g}"
            return f"Needs {line - tot:g} more · {tot:g} so far, line {line:g}" if side == "yes" else \
                f"{tot:g} so far, line {line:g}"
        if played < 0.15:                       # too early for a pace to mean anything
            return f"{tot:g} so far, line {line:g}"
        pace = tot / played
        good = pace > line if side == "yes" else pace < line
        return f"{'On track' if good else 'Not on track'} · {tot:g} so far, on pace for {pace:.0f}, line {line:g}"
    if kind == "win":
        return "Winning now" if me > opp else "Losing now" if me < opp else "Tied"
    return ""


def open_singles(max_age=30):
    """Every open single bet, spread and total in your Kalshi account, with live scores, for the Live page."""
    if time.time() - SINGLES["at"] < max_age:
        return SINGLES["items"]
    pos = ACCT_POS["items"] if time.time() - ACCT_POS["at"] < 300 else None
    if pos is None:
        key_id = CFG.get("kalshi_key_id", "").strip()
        if not key_id or not os.path.exists(KEYFILE):
            return []
        with open(KEYFILE, encoding="utf-8") as f:
            key = load_private_key(f.read())
        pos = all_positions(key, key_id)
        ACCT_POS.update(at=time.time(), items=pos)
    held = []
    for p in pos:
        t = p.get("ticker") or p.get("market_ticker")
        n = float(p.get("position_fp") or p.get("position") or 0)
        if t and not is_combo(t) and abs(n) > 0.005:
            held.append((t, n, p))
    mk, got, mk_at = {}, [], {}
    for i in range(0, len(held), 50):
        chunk = [t for t, _, _ in held[i:i + 50]]
        try:
            r = requests.get(f"{KALSHI}/markets", params={"tickers": ",".join(chunk)}, timeout=15)
            r.raise_for_status()
            ms = r.json().get("markets", [])
            got += ms
            mk.update({m.get("ticker"): m for m in ms})
            mk_at.update({m.get("ticker"): time.time() for m in ms})   # when each price was read (smart sell more)
        except (requests.RequestException, ValueError):
            mk.update({t: SINGLES["mk"][t] for t in chunk if t in SINGLES["mk"]})
    price_watch_held(held, mk)                         # Smart Buy's price recorder: the singles you hold
    price_seen_markets(got)                            # only prices read just now, never the fallback copy
    try:                                             # display only: scores for tennis, EuroLeague, UFC
        kalshi_live_kick(klive_events([{"ticker": t, "event": game_event((mk.get(t) or {}).get("event_ticker") or "")}
                                          for t, _, _ in held if not (mk.get(t) or {}).get("result")]))
    except Exception as err:
        print("kalshi live data:", type(err).__name__, err)
    out = []
    for t, n, p in held:
        m = mk.get(t) or {}
        side = "yes" if n > 0 else "no"
        n = abs(n)
        kind = _bet_kind(t)
        code = ticker_sport(t) or "other"
        yes_sub = (m.get("yes_sub_title") or "").strip()
        label = yes_sub if side == "yes" else ((m.get("no_sub_title") or "").strip() or ("Not: " + yes_sub if yes_sub else ""))
        if kind == "win" and side == "yes" and yes_sub and "win" not in yes_sub.lower():
            label = f"{yes_sub} to win"
        bid = dollars(m, "yes_bid") if side == "yes" else dollars(m, "no_bid")
        lp = live_price(m) if m else None
        chance = (lp if side == "yes" else 1 - lp) if lp is not None else (bid or None)
        cost = dollars(p, "market_exposure") or dollars(p, "total_traded")
        res = m.get("result") if m.get("result") in ("yes", "no") else None
        status = (m.get("status") or "").lower()
        sc = None
        try:
            if code in SPORTS and (SPORTS[code].get("espn") or SPORTS[code].get("feed")):
                fetch_scores(code=code)
            sc = leg_score(_score_leg(t, kind, side, code))
        except Exception:
            sc = None
        live = bool(sc) and str(sc.get("state") or "") in ("in", "live")
        state = "done" if res else "over" if status in ("closed", "settled", "finalized", "determined") else \
            "live" if live else "pre"
        rs = None                                   # started, nothing settled it, no live score: say so honestly
        ksc = None                                  # tennis, EuroLeague, UFC: Kalshi's live data, shown only
        if not sc and code in KLIVE_ANY:            # (state, and so smart sell, stay exactly as before)
            try:
                ksc = kalshi_score({"ticker": t, "side": side})
            except Exception:
                ksc = None
        if state == "pre":
            ks_detail = (ksc or {}).get("detail", "") if ksc and (ksc.get("me") is None or ksc["state"] == "post") else ""
            rs = safe_run_status(code, start_dt(game_event(m.get("event_ticker") or ""), t if kind == "win" else None),
                            score_state=(sc or ksc or {}).get("state"), detail=ks_detail)
        dsc = sc or (ksc if ksc and ksc.get("me") is not None and ksc["state"] != "pre" else None)   # the score to show
        team = re.sub(r"\s+(wins by|to win).*$", "", label or "", flags=re.I).strip() or (sc or {}).get("abbr") or t
        out.append({"t": t, "ticker": t, "name": team if kind != "total" else (label or t),
                    "opp": (dsc or {}).get("opp_name") or (dsc or {}).get("opp_abbr") or "", "live": chance if state == "live" else None,
                    "sc": {k: dsc.get(k) for k in ("me", "opp", "abbr", "opp_abbr", "detail")} if dsc else None,
                    "on": bool(ksc and not sc and ksc["state"] == "in"),       # display: Kalshi's data says it's playing
                    "src": "kalshi" if ksc and not sc else "",
                    "kind": kind, "sport": code, "side": side, "label": label or m.get("title") or t,
                    "game": (m.get("title") or "").strip(), "event": m.get("event_ticker") or "",
                    "n": round(n, 2), "cost": round(cost, 2), "pays": round(n, 2),
                    "worth": round(n * bid, 2) if bid is not None else None,
                    "chance": round(chance, 4) if chance is not None else None, "state": state, "res": res,
                    "score": re.sub(r"<[^>]+>", "", score_line(sc)) if sc and state != "pre" else
                    re.sub(r"<[^>]+>", "", score_line(dsc)) if dsc and dsc["state"] in ("in", "post") else "",
                    "starts": start_label(game_event(m.get("event_ticker") or "")) if state == "pre" and not rs else "",
                    "note": (rs or {}).get("text", ""), "phase": (rs or {}).get("phase", ""),
                    "short": (rs or {}).get("short", ""),
                    "how": _single_how(kind, side, _line_num(yes_sub), sc) if state in ("live", "over") else
                    _single_how(kind, side, _line_num(yes_sub), dsc)       # tennis lines count games, not the sets shown
                    if dsc and not sc and dsc["state"] in ("in", "post") and (code != "tennis" or kind == "win") else "",
                    "url": game_url(_score_leg(t, "win", "yes", code)["ticker"])
                    if _score_leg(t, "win", "yes", code)["ticker"].startswith(tuple(GAME_SLUG)) else ""})
    pre = MINE.setdefault("pre_single", {})          # each single's last chance before its game (loss-cut guard)
    for x in out:
        if x["state"] == "pre" and x.get("chance") is not None:
            pre[x["t"]] = x["chance"]
    for t in [t for t in pre if t not in {x["t"] for x in out}]:
        pre.pop(t, None)
    mine = self_sell_set()
    for x in out:
        x["self"] = x["t"] in mine
        m = mk.get(x["t"]) or {}
        try:
            why, fl = single_sell_reason(x, dollars(m, f"{x['side']}_bid"), None, track=False)
            x["sell_at"], x["sell_over"] = sell_line_shown(fl if (x.get("chance") or 0) >= 0.5 else 0,
                                                           sell_top(x.get("n"), single=True))
        except Exception:
            x["sell_at"], x["sell_over"] = None, False
        if x.get("sell_over") and CFG.get("exit_cap_shadow") is True:   # the switch is read here, before the bid is looked up (a missing side can't raise)
            try:
                exit_cap_shadow(x, dollars(m, f"{x['side']}_bid"))   # #375 paper record (default off, swallows its own errors)
            except Exception:
                pass
    out.sort(key=lambda x: (x["state"] != "live", x["state"] == "done", x["starts"] or "~"))   # order kept: smart sell walks it
    SINGLES.update(at=time.time(), items=out, mk=mk, mk_at=mk_at)   # a fallback copy has no stamp: never "fresh"
    return out


LIVE_EST_AGE = 90            # seconds: a leg price older than this is never used for the live-priced estimate


def live_offer_est(h, v):
    """Display-only (Refs #80): the "worth now if sold" estimate made to follow the live leg prices,
    so the Live hero's "≈" number moves with the market between leg resolutions instead of sitting on
    the frozen Monte-Carlo chance. Same shape as the current estimate — kalshi_discount(live) times a
    chance times pays — but the chance is the product of each still-open leg's fresh live Kalshi price
    (won legs count as 1), not h["p"].

    It is NEVER read by any sell/hedge/panel/auto path (those read MINE["cash"] and
    kalshi_discount(live)*h["p"]*h["pays"]); it only sits on the view dict for the Live screen.

    Returns None (so the caller falls back to the current frozen estimate, keeping the old number)
    whenever it can't be trusted:
      - same-game ("rough") combos, whose legs are correlated and so can't be multiplied as independent;
      - any still-open leg without a fresh live price (not in play / finished-but-unsettled / missing);
      - any error.
    A lost open leg (res == "no") forces the product to 0, matching the frozen estimate (h["p"] is 0
    once a leg is lost). The result is clamped to [0, pays] and never raises.
    """
    try:
        if not h or h.get("rough"):
            return None                                  # correlated same-game legs: keep the old number
        pays = v.get("pays") or 0
        if pays <= 0:
            return None
        prob = 1.0
        now, events = time.time(), set()
        for lg in v.get("legs") or []:
            res = lg.get("res")
            if res == "yes":
                continue                                 # already won: counts as 1
            if res == "no":
                prob = 0.0                               # a lost leg sinks the whole combo
                continue
            lp = lg.get("live")                          # live Kalshi price (already 1-p for NO legs)
            if lp is None:
                return None                              # an open leg with no live price: fall back
            tk = lg.get("ticker") or ""
            at = (MARKET_INFO.get(tk) or {}).get("at")
            if at is not None and now - at > LIVE_EST_AGE:
                return None                              # the price is older than the build: not "fresh", fall back
            parts = tk.split("-")
            if len(parts) >= 3:                          # two open picks in one game move together: not independent
                if parts[1] in events:
                    return None
                events.add(parts[1])
            prob *= max(0.0, min(1.0, lp))
        est = kalshi_discount(bool(v.get("live"))) * prob * pays
        return round(max(0.0, min(est, pays)), 2)
    except Exception:
        return None


def hero_worth(v):
    """Display-only: the "worth now if sold" number the Live row and hero show for one combo. The live-priced
    estimate when there is no fresh real quote and every open leg has a fresh live price, else the frozen
    `offer`. Used by cash_now and the hero chart's pulse so the row, the hero and the chart agree."""
    if not v.get("offer_real") and v.get("offer_live") is not None and v.get("offer") is not None:
        return v["offer_live"]
    return v.get("offer") or 0


def live_view(mine, views, plan, chance_one, balance):
    """Everything Combo Hub's Live screen shows, as plain data."""
    import time
    acts = (plan or {}).get("acts") or {}
    for v in views:
        t = v["t"]
        h = MINE["hold"].get(t)
        if not h:
            continue
        o = MINE["cash"].get(t) or {}
        real = fresh_offer(t) if o.get("rfq") != "estimate" else None
        v["hold_value"] = round(h["hold"], 2)
        v["won_some"] = bool(h.get("won_some"))
        v["offer"] = round(o["offer"] / max(o.get("frac", 1.0), 0.01), 2) if o.get("offer") else None
        if v["offer"] is None:                    # no offer asked for yet: what Kalshi usually pays for this
            try:
                v["offer"] = round(kalshi_discount(v["live"]) * v["p"] * v["pays"], 2)
            except Exception:
                pass
        v["offer_real"] = bool(real)
        v["offer_live"] = live_offer_est(h, v)    # display-only: estimate that follows live leg prices (Refs #80)
        v["fair_value"] = round(h["p"] * h["pays"], 2)          # what it's worth at the market's own chances
        v["overpay"] = round(v["offer"] / v["fair_value"], 3) if real and v["offer"] and v["fair_value"] > 0 else None
        v["offer_age"] = round(time.time() - o.get("at", 0)) if o.get("at") else None
        f = acts.get(t) or 0
        v["verdict"] = "sell" if f == 1 else "half" if f == 0.5 else "hold"
        try:                                       # the reasoning, in numbers and one sentence
            W = max(CFG["bankroll"], 1) + MINE.get("locked", 0)
            v["hold_ce"] = round(single_value(h["p"], h["pays"], W), 2)
            v["why"] = re.sub(r"<[^>]+>", "", plan_words(t, f, {"offer": v["offer"] or 0, "frac": 1.0}, h, W)) \
                if v["offer"] else ""
        except Exception:
            v["hold_ce"], v["why"] = None, ""
        try:
            v["threshold"], v["thr_over"] = sell_line_shown(wait_threshold(t) if h.get("won_some") else 0,
                                                            sell_top(h["pays"]))
        except Exception:
            v["threshold"], v["thr_over"] = None, False
        try:                                       # the cash-out moment: Pete's profit rules say now
            why, floor = take_profit_reason(t, h)
            v["moment"] = {"why": why, "at": round(floor, 2)} if why and (v.get("offer") or 0) >= 0.97 * floor else None
            v["nudge"] = cash_nudge(t, h, (why, floor))     # the only thing that may say "time to cash out" (#210)
        except Exception:
            v["moment"] = v["nudge"] = None
        try:
            hg = hedge_for(t)
            v["hedge"] = {k: hg.get(k) for k in ("name", "cost", "locked", "price", "done")} if hg else None
        except Exception:
            v["hedge"] = None
    alive = [v for v in views if v["group"] in ("pending", "won")]
    need = {}
    for v in views:
        if v["group"] != "pending":
            continue
        for lg in v["legs"]:
            if lg["res"]:
                continue
            k = (lg["ticker"], lg["side"])
            x = need.setdefault(k, {"name": lg["name"], "opp": lg["opp"], "sport": lg["sport"], "combos": 0, "pays": 0.0,
                                    "ticker": lg["ticker"],
                                    "state": lg["state"], "score": lg["score"], "sc": lg["sc"], "starts": lg["starts"],
                                    "phase": lg.get("phase", ""), "note": lg.get("note", ""), "short": lg.get("short", ""),
                                    "chance": lg["live"] if lg["live"] is not None else lg["chance"]})
            x["combos"] += 1
            x["pays"] += v["pays"]
    games = sorted(need.values(), key=lambda x: (x["state"] != "live", -x["combos"]))
    try:
        singles = open_singles()
    except Exception as err:
        print("singles on Live:", type(err).__name__, err)
        singles = []
    label_bets(singles, views)                       # display only: what each bet is, and which game
    try:
        seed_origins([v["t"] for v in views if v["group"] == "pending"] + [x["t"] for x in singles])
        mine_sell = self_sell_set()
        for v in views:
            v["own"] = v["group"] == "pending" and is_own(v["t"])
            v["self"] = v["t"] in mine_sell
        for x in singles:
            x["own"] = is_own(x["t"])
            x["self"] = x["t"] in mine_sell
        note_held({game_event(l.get("event") or "") for a in mine if a.get("status") == "pending" and is_own(a["ticker"])
                   for l in a["legs"]} | {game_event(x["event"]) for x in singles if x["own"]})
    except Exception as err:
        print("bet origins:", type(err).__name__, err)
    week_ago = (dt.date.today() - dt.timedelta(days=7)).isoformat()
    settled = [a for a in (MINE.get("acct") or mine) if a["status"] in ("won", "lost", "cashed") and (a.get("week") or "") >= week_ago]
    week_pl = sum((a["back"] if a["status"] == "cashed" else a["pays"] if a["status"] == "won" else 0) - a["cost"]
                  for a in settled)
    today = day_money(MINE.get("acct") or mine)
    return {"at": time.time(), "balance": balance, "combos": views, "today": today, "singles": singles,
            "auto_sell": bool(CFG.get("auto_sell")),
            "riding": sum(1 for v in views if v["group"] == "pending"),
            "staked": round(sum(v["cost"] for v in views if v["group"] == "pending"), 2),
            "chance_one": chance_one, "best": max((v["pays"] for v in alive), default=0),
            # display-only; same rule as the combo row (SPA rowLive): a row with no offer shows "—", so it adds nothing here
            "cash_now": round(sum(hero_worth(v) for v in views if v["group"] == "pending"), 2),
            "hold_value": round(sum(h["hold"] for h in MINE["hold"].values()), 2),
            "locked": MINE.get("locked", 0), "week_pl": round(week_pl, 2), "games": games[:30],
            "risk": max(games, key=lambda x: (x["combos"], x["pays"])) if games else None,
            "todo": [v["t"] for v in views if v.get("verdict") in ("sell", "half") and v.get("offer_real")]}


def plan_cashout():
    """Best mix of hold / cash out half / cash out all across your live combos, judged
    together (combos that need the same team rise and fall together) and weighed for
    your bankroll. Only combos with a fresh Kalshi offer can be cashed."""
    offers = [t for t in MINE["hold"] if fresh_offer(t)]
    if not offers or not MINE.get("patterns"):
        MINE["advised"] = set()
        return None
    acts = {t: 0.0 for t in offers}
    best = weekend_stats(acts)["worth"]
    for _ in range(3):
        changed = False
        for t in sorted(offers, key=lambda x: -MINE["hold"][x]["hold"]):
            h = MINE["hold"][t]
            if not h.get("won_some"):
                continue        # nothing earned yet (no pick won, no big in-game gain): hold for the upside
            bar = wait_threshold(t) * (0.97 if t in MINE.get("advised", set()) else 1.0)
            if acts_price(t) * h["pays"] < bar:
                continue        # waiting at least one more game is worth more than this offer
            for f in (0.0, 0.5, 1.0):
                if f == acts[t]:
                    continue
                trial = dict(acts, **{t: f})
                v = weekend_stats(trial)["worth"]
                if v > best + 0.25:               # ignore changes worth only pennies
                    best, acts, changed = v, trial, True
        if not changed:
            break
    MINE["advised"] = {t for t, f in acts.items() if f}      # sticky: needs a 3% drop to flip back
    return {"acts": acts, "plan": weekend_stats(acts), "hold": weekend_stats({t: 0.0 for t in offers})}


def chance_pct(c):
    """'64%', but an open pick is never called a sure thing: 99.5% and up (short of 1) reads '>99%' (issue #224)."""
    return ">99%" if 0.995 <= c < 1 else f"{c:.0%}"


def plan_words(t, f, o, h, W):
    """One short reason for the verdict on one combo."""
    p, pays = h["p"], h["pays"]
    shared = any(sum(1 for x in MINE["hold"].values() if k in dict(x["need"])) > 1 for k, _ in h["need"])
    if f == 1:
        return f"A sure {money(o['offer'])} beats a {p:.0%} shot at {money(pays)} for you." + \
            (" Also spreads risk off a game your other combos need." if shared else "")
    if f == 0.5:
        return f"Locks in half and keeps a {p:.0%} shot at {money(pays / 2)}."
    thr = wait_threshold(t)
    if h.get("won_some") and thr > o["offer"] / max(o.get("frac", 1.0), 0.01):
        nxt = (h.get("legs_left") or [(0, False, 0)])[0]
        shown, over = sell_line_shown(thr, sell_top(pays))      # never "cash out at $14" on a $13 combo (#371)
        return (f"Waiting is worth more: {'the game under way' if nxt[1] else 'the next game'} "
                f"({chance_pct(nxt[0])} to go your way) makes this combo worth more to sell after. "
                + (f"No offer can beat waiting: it pays {money(pays)} at most." if over else
                   f"Worth cashing out at about ${shown:,.2f}."))
    return f"Holding is worth about {money(single_value(p, pays, W))} to you, more than this offer."

def confirm_parts(t, h, o):
    """(title, details, url, button) for the confirm sheet: exactly what happens."""
    what = "half of " if o.get("frac", 1.0) < 1 else ""
    title = (f"Cash out {what}{h['label']} for {money(o['offer'])}? "
             f"({gain_words(o['offer'], h['cost'] * o.get('frac', 1.0))})")
    sub = (f"You paid {money(h['cost'] * o.get('frac', 1.0))}. If you hold instead: "
           f"{h['p']:.0%} chance of {money(h['pays'] * o.get('frac', 1.0))}.")
    return title, sub, f"combo://cash/go/{t}", f"Cash out for {money(o['offer'])}"


def confirm_cash(t, h, o):
    """onclick for a Cash out button: a bottom sheet that says exactly what happens."""
    args = ",".join(json.dumps(x) for x in confirm_parts(t, h, o))
    return html.escape(f"sheet({args})")


def gain_words(amount, paid):
    """'+$10 profit' / '$2 loss' / 'break even' for getting `amount` back on `paid`."""
    d = amount - paid
    if abs(d) < 0.5:
        return "break even"
    return f"+{money(d)} profit" if d > 0 else f"{money(-d)} loss"


def cash_label(name, f, amount, paid, about=False):
    """Two-line cash-out button: what you'd make first, then what you get back and paid."""
    return (f"<span class='bt'>Cash out {'half of ' if f < 1 else ''}{name} · {'about ' if about else ''}"
            f"{gain_words(amount, paid)}</span>"
            f"<span class='bs'>get {money(amount)} · you paid {money(paid)}</span>")


def action_button(t, f, h):
    """The button that carries out the plan for one combo (needs an offer of the right size)."""
    o = fresh_offer(t)
    te = html.escape(t)
    if not o or f == 0:
        return ""
    if abs(o.get("frac", 1.0) - f) < 0.01:
        return (f"<button class='btn go cashb two' onclick=\"{confirm_cash(t, h, o)}\">"
                f"{cash_label(html.escape(h['label']), f, o['offer'], h['cost'] * f)}</button>")
    # Kalshi quotes one size at a time, so this price is worked out from the offer in hand;
    # tapping gets the exact offer for this size and asks you to confirm it.
    est = acts_price(t) * h["pays"] * f
    act = "askhalfgo" if f < 1 else "askgo"
    return (f"<button class='btn go cashb two' onclick=\"cash('{act}','{te}')\">"
            f"{cash_label(html.escape(h['label']), f, est, h['cost'] * f, about=True)}</button>")


def cash_block(ticker, plan):
    """The short hold-or-cash-out box on a live combo card."""
    h = MINE["hold"].get(ticker)
    if not h:
        return ""
    t = html.escape(ticker)
    W = max(CFG["bankroll"], 1) + MINE.get("locked", 0)
    p, pays = h["p"], h["pays"]
    pct = f"{p:.0%}" if p >= 0.01 or p == 0 else f"{p:.1%}"
    out = [f"<div class='min cashbox'>If you hold: <b>{pct}</b> chance of <b>{gain_words(pays, h['cost'])}</b>"
           f" <span class='muted'>({money(pays)} back)</span>"
           + ("<div class='muted' style='font-size:12px;margin-top:4px'>Chance from Kalshi's price for the whole "
              "combo: its picks are in the same game and move together.</div>" if h.get("rough") else "")]
    if CFG.get("auto_sell") and can_trade() and not h.get("rough"):
        thr, over = sell_line_shown(wait_threshold(ticker), sell_top(pays))   # never above what it pays (#371)
        who = f"your {wname()}" if in_pythonista() and watcher_alive() else "it"
        out.append(f"<div class='muted' style='font-size:13px;margin-top:6px'>🤖 Auto cash-out is on: {who} "
                   + ("waits until a pick in this combo has won." if not h.get("won_some") else
                      f"won't cash out just to beat the next game: no offer can beat waiting (it pays {money(pays)} at most). "
                      f"Your other sell rules still apply." if over else
                      f"sells by itself if Kalshi offers about ${thr:,.2f} or more." if thr
                      else "waits until a pick in this combo has won.") + "</div>")
    tp = (MINE.get("tp") or {}).get(ticker)
    if tp:
        st = order_steps(tp)
        left = sum(k for k, _ in st) or pays
        what = (" / ".join(money(pr * left) for _, pr in st) + " <span class='muted'>(thirds, whole-combo prices)</span>"
                if len(st) > 1 else money(st[0][1] * left))
        guard = any(live for _, live, _ in (MINE["hold"].get(ticker) or {}).get("legs_left", []))
        out.append(f"<div class='quote' style='justify-content:space-between'><span style='font-size:14px'>🎯 <b>Auto-sell is on</b>: Kalshi sells it if a buyer pays "
                   f"<b>{what}</b>" + ("<br><span class='muted' style='font-size:12px'>A game is on: priced as if "
                                        "your pick wins, so no one can buy cheap off a swing.</span>" if guard else "")
                   + f"</span><button class='btn quiet cashb' onclick=\"cash('tpx','{t}')\">Cancel</button></div>")
    elif AUTOSELL and can_trade():
        target, why = tp_target(h["cost"], pays, ticker)
        if target:
            at = ("starting at " if "thirds" in why else "at ") + money(target)
            out.append(f"<div class='quote' style='display:block'><div style='font-size:14px;margin-bottom:8px'>"
                       f"<b>Auto-sell is off</b> for this combo. <span class='muted'>Turn it on and Kalshi sells it "
                       f"for you if a buyer pays {at}, even while you're away.</span></div>"
                       f"<button class='btn cashb' onclick=\"cash('tp','{t}')\">Turn on auto-sell {at}</button>"
                       f"<div class='muted' style='font-size:13px;margin-top:6px'>{html.escape(why.strip('()'))}"
                       f" · cancel any time</div></div>")
    raw = MINE["cash"].get(ticker)
    o = fresh_offer(ticker)
    if raw and raw.get("error"):
        out.append(f"<div class='muted' style='font-size:13px;margin-top:6px'>{html.escape(raw['error'])}</div>")
    if o:
        f = (plan or {}).get("acts", {}).get(ticker, 0.0)
        word, cls = {1.0: ("Cash out", "ok"), 0.5: ("Cash out half", "ok")}.get(f, ("Hold", "no"))
        size = " for half" if o.get("frac", 1.0) < 1 else ""
        main = action_button(ticker, f, h) if f else ""
        if main:                                  # inside its own card the combo's name is implied
            main = re.sub(r"(Cash out(?: half)?)(?: of)? " + re.escape(html.escape(h["label"])) + r"\b", r"\1", main)
        if not main:
            main = (f"<button class='btn cashb' onclick=\"{confirm_cash(ticker, h, o)}\">Cash out"
                    f"{' half' if size else ''} for {money(o['offer'])}</button>")
        out.append(f"<div style='margin-top:8px'>Kalshi offers <b>{money(o['offer'])}</b>{size} "
                   f"<span class='verdict {cls}'>{word}</span></div>"
                   f"<div class='muted' style='font-size:13px;margin-top:4px'>{plan_words(ticker, f, o, h, W)}</div>"
                   + insurance_words(h, o) +
                   f"<div class='quote pair'>{main}<button class='btn cashb' onclick=\"cash('no','{t}')\">Keep it</button></div>"
                   + hedge_block(ticker, h, o))
    else:
        tag = "<span class='tag good'>Worth checking</span> " if h["worth"] else ""
        out.append(f"<div class='quote'>{tag}<button class='btn cashb' onclick=\"cash('ask','{t}')\">"
                   f"Get cash-out offer</button></div>" + hedge_block(ticker, h, None))
    out.append("</div>")
    return "".join(out)


# ---------------------------------------------------------------- hedging
HEDGES = os.path.join(HERE, "combo_hedges.json")   # combo -> contracts of the other side already bought
FEE_RATE = 0.07                                     # Kalshi's trading fee: about 7% x price x (1 - price)


def qty(x):
    """A contract count as Kalshi shows it: 41.67, 42."""
    return f"{x:,.2f}".rstrip("0").rstrip(".")


def hedge_for(ticker, price=None):
    """For a combo down to its last pick: buying the other side of that game so you collect about
    the same whichever team wins. {ticker, name, price, n, cost, locked, done} or None. `price` (a fresh
    ask from the order book) replaces the last board price."""
    h = MINE["hold"].get(ticker) or {}
    need = h.get("need") or []
    if len(need) != 1:
        return None
    (side, leg_t), _ = need[0]
    for sides in (MINE.get("all_games") or {}).values():
        mine = next((x for x in sides if x["ticker"] == leg_t), None)
        if mine:
            if any(x.get("tie") for x in sides):
                return None                       # a draw is possible: no single hedge covers it (yet)
            other = next((x for x in sides if x is not mine), None)
            buy = other if side == "yes" else mine
            break
    else:
        return None
    q = (price if price is not None else buy.get("p")) if buy else None
    if not q or not 0.01 <= q <= 0.97:
        return None
    done = (load_json(HEDGES, {}).get(ticker) or {}).get("n", 0.0)
    n = math.floor((h["pays"] - done) * 100) / 100
    if n < 1:
        return {"ticker": buy["ticker"], "name": buy["pick"], "done": done, "n": 0}
    fee = math.ceil(FEE_RATE * n * q * (1 - q) * 100) / 100
    cost = n * q + fee
    return {"ticker": buy["ticker"], "name": buy["pick"], "price": q, "n": n, "fee": fee,
            "cost": cost, "locked": n - cost, "done": done}


def hedge_unknown(err):
    """Whether a failed hedge order may still have gone through (no answer, a lost connection, a Kalshi server
    error): then it is marked 'check' and never retried."""
    return order_outcome(err) == "unknown"


def place_hedge(ticker, hg=None, auto=False):
    """Buy the other side of the last pick's game, at today's price or not at all (fills now or
    cancels). Runs after you confirm, or from guarded auto-hedge with `hg` priced on a fresh order book.
    An order whose outcome is unknown is marked 'check' (never retried) and the message starts with ⚠️.
    Returns a message."""
    import uuid
    h = MINE["hold"].get(ticker) or {}
    if hedge_unsure(ticker):                          # an earlier hedge here may have filled (or wasn't saved): never again
        return (f"⚠️ An earlier hedge on {h.get('label', 'this combo')} had no clear answer or couldn't be saved, so "
                "nothing was bought. Check Kalshi first.")
    hg = hg or hedge_for(ticker)
    if not hg or not hg.get("n"):
        return "Nothing to hedge on this combo now."
    if auto and hold_refusal("buy", strict=True)[0]:               # Kalshi is refusing this account's orders: no automatic hedge (#134)
        return "The hedge wasn't placed: Kalshi isn't allowing orders for your account right now."

    def unsure(err):
        try:
            hedges_update(ticker, check=int(time.time()), check_ticker=hg["ticker"], name=hg["name"])
        except Exception:
            _HEDGE_UNSURE_MEM[ticker] = {"check": int(time.time())}   # logged loudly; still marked in memory
        ACCT_CACHE["at"] = 0
        return (f"⚠️ The hedge on {h.get('label', 'the combo')} ({hg['name']}) may or may not have gone through "
                f"({type(err).__name__}). Check Kalshi. It won't be tried again"
                + (", and auto cash-out leaves this combo alone." if auto else "."))
    body = {"ticker": hg["ticker"], "side": "bid", "count": f"{hg['n']:.2f}", "price": f"{hg['price']:.4f}",
            "time_in_force": "immediate_or_cancel", "self_trade_prevention_type": "taker_at_cross",
            "client_order_id": str(uuid.uuid4())}
    try:                                       # V2, with the legacy fallback inside kalshi_send's order adapter
        r = kalshi_send("POST", "/portfolio/events/orders", body) or {}
        filled = float(r.get("fill_count") or 0)
    except PermissionError as err:
        return f"The hedge wasn't placed. {err}"
    except Exception as err:
        return unsure(err) if hedge_unknown(err) else f"Kalshi didn't take the hedge: {order_words(err)}"
    ACCT_CACHE["at"] = 0
    if filled <= 0:
        return f"No one was selling {hg['name']} at {hg['price'] * 100:.0f}¢ just now. Nothing was bought."
    try:
        hedges_update(ticker, n=round(hg["done"] + filled, 2), ticker=hg["ticker"], name=hg["name"])
    except Exception as err:                            # bought, but not remembered: hands off this combo until checked
        print(f"MONEY STATE NOT SAVED: hedge on {ticker[:80]}: {type(err).__name__}: {err}", flush=True)
        _HEDGE_UNSURE_MEM[ticker] = {"check": int(time.time()), "why": "hedge bought but not saved"}
    haptic("success")
    locked = filled * (1 - hg["price"]) - hg["fee"] * filled / hg["n"]
    if filled + 0.01 < hg["n"]:
        return (f"✅ Hedged part of {h.get('label', 'the combo')}: bought {qty(filled)} of {qty(hg['n'])} {hg['name']} at "
                f"{hg['price'] * 100:.0f}¢. Tap Hedge again for the rest at the new price.")
    return (f"✅ Hedged {h.get('label', 'the combo')}: bought {qty(filled)} {hg['name']} at {hg['price'] * 100:.0f}¢. "
            f"You collect about {money(filled)} whichever team wins: about {money(locked)} locked in after the hedge.")


def hedge_block(ticker, h, o):
    """Card lines: what hedging locks in, next to the cash-out offer, with its own confirm."""
    hg = hedge_for(ticker)
    if not hg:
        return ""
    if not hg.get("n"):
        return (f"<div class='muted' style='font-size:13px;margin-top:6px'>🛡 Hedged with {qty(hg['done'])} "
                f"{html.escape(hg['name'])}: you collect about the same whichever team wins.</div>")
    if hg["locked"] <= 0:
        return ""
    vs = ""
    if o:
        diff = hg["locked"] - o["offer"] / max(o.get("frac", 1.0), 0.01)
        vs = (f" That's <b>{money(diff)} more</b> than cashing out." if diff > 0.5 else
              f" Cashing out gets {money(-diff)} more." if diff < -0.5 else " About the same as cashing out.")
    title = (f"Hedge {h['label']}: buy {qty(hg['n'])} {hg['name']} at {hg['price'] * 100:.0f}¢ "
             f"({money(hg['cost'])})?")
    sub = (f"You'd collect about {money(hg['n'])} whichever team wins, so about {money(hg['locked'])} is locked in "
           f"({gain_words(hg['locked'], h['cost'])}). Buys now at {hg['price'] * 100:.0f}¢ or not at all; fee about "
           f"{money(hg['fee'])}.")
    args = ",".join(json.dumps(x) for x in (title, sub, f"combo://cash/hedgego/{ticker}", f"Hedge · lock in {money(hg['locked'])}"))
    return (f"<div style='margin-top:10px;font-size:14px'>🛡 <b>Or hedge:</b> buy {qty(hg['n'])} {html.escape(hg['name'])} at "
            f"{hg['price'] * 100:.0f}¢ ({money(hg['cost'])}) and collect about {money(hg['n'])} either way: locks in "
            f"<b>{money(hg['locked'])}</b>.{vs}</div><div class='quote'><button class='btn quiet cashb' "
            f"onclick=\"{html.escape(f'sheet({args})')}\">Hedge · lock in {money(hg['locked'])}</button></div>")


def insurance_words(h, o):
    """What cashing out gives up vs holding, on average: the price of a sure thing."""
    if not o:
        return ""
    whole = o["offer"] / max(o.get("frac", 1.0), 0.01)
    gap = h["p"] * h["pays"] - whole
    if gap < 0.5:
        return ""
    return (f"<div class='muted' style='font-size:13px;margin-top:4px'>Cashing out gives up about {money(gap)} "
            f"on average vs. holding, in exchange for a sure {money(whole)}.</div>")


